package api.auth.kimdeo.utils

import kotlin.math.abs

object Credits {
    const val INITIAL_CREDITS = 100
    const val CREATE_JOB_CREDITS = 10
    private const val TEXT_FROM_MEDIA_CREDITS = 12
    private const val VOICE_CREDITS = 15
    private const val VOICE_OVER_CREDITS = 20

    fun textFromMedia(numWords: Int?): Int {
        if (numWords == null) return TEXT_FROM_MEDIA_CREDITS
        val n = abs(50 % numWords)
        return if (n <= 1) 12 else n * 12
    }

    fun voiceFromMedia(numWords: Int?): Int {
        if (numWords == null) return VOICE_CREDITS
        val n = abs(50 % numWords)
        return if (n <= 1) 15 else n * 15
    }

    fun voiceOverMedia(numWords: Int?): Int {
        if (numWords == null) return VOICE_OVER_CREDITS
        val n = abs(50 % numWords)
        return if (n <= 1) 20 else n * 20
    }
}