package api.auth.kimdeo.model

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable


@Serializable
data class OneTimePayModel(
    @SerialName("data")
    val `data`: Data?,
    @SerialName("message")
    val message: String?,
    @SerialName("status")
    val status: Boolean?
) {
    @Serializable
    data class Data(
        @SerialName("access_code")
        val accessCode: String?,
        @SerialName("authorization_url")
        val authorizationUrl: String?,
        @SerialName("reference")
        val reference: String?
    )
}


@Serializable
data class SubscriptionModel(
    val subscriptionId: String,
    val userId: String,
    val referenceId: String? = null,
    val email: String,
    val subscriberEmail: String?,
    val customerCode: String?,
    val emailToken: String?,
    val planInterval: PlanInterval? = null,
    val planCode: String?,
    val subscriptionCode: String?,
    val authorizationCode: String?,
    val createdAt: Long,
    val updatedAt: Long,
    val credits: Int,
) {
    fun clean(): SubscriptionModel {
        return SubscriptionModel(
            userId = userId.trim(),
            email = email.trim(),
            planCode = planCode?.trim(),
            subscriptionCode = subscriptionCode?.trim(),
            authorizationCode = authorizationCode?.trim(),
            customerCode = customerCode?.trim(),
            emailToken = emailToken?.trim(),
            createdAt = createdAt,
            updatedAt = updatedAt,
            credits = credits,
            subscriberEmail = subscriberEmail?.trim(),
            referenceId = referenceId?.trim(),
            planInterval = planInterval,
            subscriptionId = subscriptionId
        )
    }

}



@Serializable
data class PayStackInitTransaction(
    @SerialName("email")
    val email: String,
    @SerialName("plan")
    val plan: String,
    @SerialName("amount")
    val amount: String,
    @SerialName("reference")
    val referenceId: String
)


@Serializable
data class SubscriptionPayModel(
    @SerialName("data")
    val `data`: Data?,
    @SerialName("message")
    val message: String?,
    @SerialName("status")
    val status: Boolean?
) {
    @Serializable
    data class Data(
        @SerialName("access_code")
        val accessCode: String?,
        @SerialName("authorization_url")
        val authorizationUrl: String?,
        @SerialName("reference")
        val reference: String?
    )
}
