package api.auth.kimdeo.ui

import androidx.compose.foundation.isSystemInDarkTheme
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Shapes
import androidx.compose.material3.Typography
import androidx.compose.material3.darkColorScheme
import androidx.compose.material3.lightColorScheme
import androidx.compose.runtime.Composable
import androidx.compose.ui.text.TextStyle
import androidx.compose.ui.text.font.FontFamily
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import kimdeoauth.composeapp.generated.resources.Res
import kimdeoauth.composeapp.generated.resources.Roboto_Condensed_Bold
import kimdeoauth.composeapp.generated.resources.Roboto_Condensed_Medium
import kimdeoauth.composeapp.generated.resources.Roboto_Condensed_Regular
import org.jetbrains.compose.resources.Font

val InterFontFamily
    @Composable get() = FontFamily(
        fonts = listOf(
            Font(Res.font.Roboto_Condensed_Regular, FontWeight.Normal),
            Font(Res.font.Roboto_Condensed_Medium, FontWeight.Medium),
            Font(Res.font.Roboto_Condensed_Bold, FontWeight.Bold)
        )
    )


private val AppTypography
    @Composable get() = Typography(
        headlineLarge = TextStyle(
            fontFamily = InterFontFamily,
            fontSize = 40.sp,
            fontWeight = FontWeight.Bold
        ),
        headlineMedium = TextStyle(
            fontFamily = InterFontFamily,
            fontSize = 35.sp,
            fontWeight = FontWeight.Bold
        ),
        headlineSmall = TextStyle(
            fontFamily = InterFontFamily,
            fontSize = 30.sp,
            fontWeight = FontWeight.Bold
        ),

        bodyLarge = TextStyle(
            fontFamily = InterFontFamily,
            fontSize = 20.sp,
            fontWeight = FontWeight.SemiBold
        ),
        bodyMedium = TextStyle(
            fontFamily = InterFontFamily,
            fontWeight = FontWeight.SemiBold,
            fontSize = 15.sp
        ),
        bodySmall = TextStyle(
            fontFamily = InterFontFamily,
            fontWeight = FontWeight.SemiBold,
            fontSize = 10.sp
        ),
    )

private val HighContrastShapes = Shapes(
    // Used for small elements like Tooltips, Badges
    extraSmall = RoundedCornerShape(2.dp),

    // Used for Buttons, TextFields, Floating Action Buttons (FABs)
    small = RoundedCornerShape(4.dp),

    // Used for Cards, Snackbars, Menus
    medium = RoundedCornerShape(8.dp),

    // Used for Dialogs, Navigation Drawers
    large = RoundedCornerShape(12.dp),

    // Used for Bottom Sheets, Full-screen overlays
    extraLarge = RoundedCornerShape(16.dp)
)

private val HighContrastLightColorScheme = lightColorScheme(
    primary = HCLightPrimary,
    onPrimary = HCLightOnPrimary,
    secondary = HCLightSecondary,
    onSecondary = HCLightOnSecondary,
    background = HCLightBackground,
    onBackground = HCLightOnBackground,
    surface = HCLightSurface,
    onSurface = HCLightOnSurface,
    error = HCLightError,
    onError = HCLightOnError
)

private val HighContrastDarkColorScheme = darkColorScheme(
    primary = HCDarkPrimary,
    onPrimary = HCDarkOnPrimary,
    secondary = HCDarkSecondary,
    onSecondary = HCDarkOnSecondary,
    background = HCDarkBackground,
    onBackground = HCDarkOnBackground,
    surface = HCDarkSurface,
    onSurface = HCDarkOnSurface,
    error = HCDarkError,
    onError = HCDarkOnError
)

@Composable
fun KimDeoHighContrastAppTheme(
    darkTheme: Boolean = isSystemInDarkTheme(),
    content: @Composable () -> Unit
) {
    val colorScheme = if (darkTheme) {
        HighContrastDarkColorScheme
    } else {
        HighContrastLightColorScheme
    }

    MaterialTheme(
        colorScheme = colorScheme,
        typography = AppTypography,
        shapes = HighContrastShapes, content = content
    )
}