package api.auth.kimdeo.model

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable



@Serializable
data class TranscribeJobModel(
    val transcriptionId: String,
    val userId: String,
    val filePath: String,
    val filePaths: List<FilePathModel> = emptyList(),
    val mediaJsonPath: String,
    val language: KimLanguage,
    val fileType: FileType,
    val outputAudioPath: String?,
    val outputVideoPath: String?,
    val outputSubtitlePath: String?,
    val jobStatus: JobStatus,
    val transcribeType: TranscribeType,
    val createdAt: Long,
    val message: String,
    val errorMessage: String = "",
    val completePercent: Int = 0,
    val numOfWords: Int,
    val mediaDuration: Double,
)

@Serializable
enum class TranscribeType {
    VIDEO_PLAYER,
    TRANSCRIPTION,
    NONE,
}


@Serializable
enum class JobStatus {
    QUEUED,
    PROCESSING,
    COMPLETED,
    FAILED;

    companion object {
        fun getJobStatus(status: String): JobStatus {

            return when (status) {
                QUEUED.name -> QUEUED
                PROCESSING.name -> PROCESSING
                COMPLETED.name -> COMPLETED
                FAILED.name -> FAILED
                else -> FAILED
            }
        }
    }
}


@Serializable
data class FromLocalMediaModel(
    val logInModel: LogInModel,
    val filePath: String,
    val jobId: String,
    val languageCode: String,
    val addWordTimestamp: Boolean,
    val hasMultilingual: Boolean,
    val bgVolume: Double,
)


@Serializable
sealed class JobMessage {
    @Serializable
    @SerialName("initial")
    data class Initial(val jobs: List<TranscribeJobModel>) : JobMessage()

    @Serializable
    @SerialName("update")
    data class Update(val job: TranscribeJobModel) : JobMessage()
}

@Serializable
data class JobRequestModel(
    val jobId: String? = null,
    val logInModel: LogInModel
)