package api.auth.kimdeo.core

import KimdeoAuth.composeApp.BuildConfig
import api.auth.kimdeo.model.InvokeLogIn
import api.auth.kimdeo.model.UserToken
import api.auth.kimdeo.screens.ScreenType
import com.russhwolf.settings.Settings
import com.russhwolf.settings.get
import com.russhwolf.settings.set
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.async
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.onStart
import kotlinx.coroutines.withContext
import kotlinx.serialization.json.Json

object PreferenceManager {
    // This will use localStorage on Wasm/JS

    private const val SCREENKEY = "SCREENKEY"
    private const val USERKEY = "USERKEY"
    private const val INVOKELOGINKEY = "INVOKELOGINKEY"
    private val settings = Settings()
    private val screenUpdates = MutableSharedFlow<ScreenType>(replay = 1)
    private val invokeLoginUpdates = MutableSharedFlow<InvokeLogIn>(replay = 1)

    suspend fun saveUserToken(userToken: UserToken) {
        withContext(Dispatchers.Default) {
            // Fire off all three encryptions concurrently
            val emailDeferred =
                async { CryptoUtils.encryptData(BuildConfig.EMAIL_CRYPTO_KEY, userToken.email) }
            val userIdDeferred =
                async { CryptoUtils.encryptData(BuildConfig.USERID_CRYPTO_KEY, userToken.userId) }
            val passwordDeferred = async {
                CryptoUtils.encryptData(
                    BuildConfig.PASSWORD_CRYPTO_KEY,
                    userToken.password
                )
            }

            // Await the results
            val newUserToken = UserToken(
                email = emailDeferred.await(),
                userId = userIdDeferred.await(),
                password = passwordDeferred.await()
            )
            settings[USERKEY] = Json.encodeToString(newUserToken)
        }
    }

    fun saveScreen(screenType: ScreenType) {
        settings[SCREENKEY] = Json.encodeToString(screenType)
        screenUpdates.tryEmit(screenType)

    }

    fun saveInvokeLogin(invokeLogIn: InvokeLogIn) {
        settings[INVOKELOGINKEY] = Json.encodeToString(invokeLogIn)
        invokeLoginUpdates.tryEmit(invokeLogIn)

    }


    suspend fun getUserToken(): UserToken? {
        return withContext(Dispatchers.Default) {
            val user = settings.getStringOrNull(USERKEY) ?: return@withContext null
            val userToken = Json.decodeFromString<UserToken>(user)
            // Fire off all three decryptions concurrently
            val emailDeferred =
                async { CryptoUtils.decryptData(BuildConfig.EMAIL_CRYPTO_KEY, userToken.email) }
            val userIdDeferred =
                async { CryptoUtils.decryptData(BuildConfig.USERID_CRYPTO_KEY, userToken.userId) }
            val passwordDeferred = async {
                CryptoUtils.decryptData(
                    BuildConfig.PASSWORD_CRYPTO_KEY,
                    userToken.password
                )
            }

            // Await the results and return the mapped object
            return@withContext UserToken(
                email = emailDeferred.await(),
                userId = userIdDeferred.await(),
                password = passwordDeferred.await()
            )
        }
    }

    fun getScreen(): ScreenType {
        val st = settings[SCREENKEY, ScreenType.TRANSCRIBING.name]
        return runCatching {
            Json.decodeFromString<ScreenType>(st)
        }.getOrDefault(ScreenType.TRANSCRIBING)
    }

    fun getInvokeLogin(): InvokeLogIn {
        val st = settings[INVOKELOGINKEY, Json.encodeToString(InvokeLogIn.empty())]
        return runCatching {
            Json.decodeFromString<InvokeLogIn>(st)
        }.getOrDefault(InvokeLogIn.empty())
    }


    fun getScreenFlow() = screenUpdates
        .map { getScreen() }
        .onStart { emit(getScreen()) }

    fun getInvokeLoginFlow() = invokeLoginUpdates
        .onStart { emit(getInvokeLogin()) }


    fun clear() {
        settings.clear()
    }
}
