@Composable
fun Modifier.outline(
    color: Color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.5f),
    bgColor: Color = MaterialTheme.colorScheme.background,
    padding: Dp = PixelDensity.VERY_SMALL,
    width: Dp = PixelDensity.getPixelDensity(1),
    shape: Shape = MaterialTheme.shapes.medium

): Modifier = composed {
    this
        .border(
            width = width,
            color = color,
            shape = shape
        )
        .background(
            color = bgColor,
            shape = shape
        )
        .padding(padding)
}

@Composable
fun Modifier.outlineBrush(
    colors: List<Color>,
    padding: Dp = PixelDensity.VERY_SMALL,
    width: Dp = PixelDensity.getPixelDensity(1),
    shape: Shape = MaterialTheme.shapes.medium

): Modifier = composed {
    this
        .border(
            brush = Brush.linearGradient(colors = colors),
            width = width,
            shape = shape
        )
        .padding(padding)
}


@Composable
fun Modifier.verticalScrollable(
    vScrollState: ScrollState = rememberScrollState(),
    enabled: Boolean = true
): Modifier = composed {
    // Create draggable state only when needed
    val draggableState = remember {
        DraggableState { delta ->
            vScrollState.dispatchRawDelta(-delta)
        }
    }

    this.then(
        Modifier.verticalScroll(state = vScrollState)
            .draggable(
                enabled = enabled,
                orientation = Orientation.Vertical,
                state = draggableState,
                startDragImmediately = false
            )
    )
}

@Composable
fun Modifier.horizontalScrollable(
    vScrollState: ScrollState = rememberScrollState(),
    enabled: Boolean = true
): Modifier = composed {
    // Create draggable state only when needed
    val draggableState = remember {
        DraggableState { delta ->
            vScrollState.dispatchRawDelta(-delta)
        }
