    this.then(
        Modifier.horizontalScroll(state = vScrollState)
            .draggable(
                enabled = enabled,
                orientation = Orientation.Horizontal,
                state = draggableState,
                startDragImmediately = false
            )
    )
}


@Composable
fun Modifier.underline(
    color: Color = Color.Black,
    thickness: Dp = PixelDensity.getPixelDensity(1),
    alpha: Float = 1f,
    paddingBottom: Dp = PixelDensity.getPixelDensity(3),
    lineCap: StrokeCap = StrokeCap.Butt
): Modifier = this.then(
    drawBehind {
        val strokeWidth = thickness.toPx()
        val y = size.height + paddingBottom.toPx()

        drawLine(
            color = color.copy(alpha = alpha),
            start = Offset(0f, y),
            end = Offset(size.width, y),
            strokeWidth = strokeWidth,
            cap = lineCap
        )
    }
)


@Composable
fun Modifier.dashedUnderline(
    color: Color = Color.Black,
    thickness: Dp = 1.dp,
    dashLength: Dp = 4.dp,
    gapLength: Dp = 4.dp,
    paddingBottom: Dp = 4.dp
): Modifier = this.then(
    drawBehind {
        val strokeWidth = thickness.toPx()
        val dashSize = dashLength.toPx()
        val gapSize = gapLength.toPx()
        val y = size.height - paddingBottom.toPx()

        var startX = 0f
        val path = Path()

        while (startX < size.width) {
            path.moveTo(startX, y)
            path.lineTo(minOf(startX + dashSize, size.width), y)
            startX += dashSize + gapSize
        }

        drawPath(
            path = path,
            color = color,
            style = Stroke(
                width = strokeWidth,
                cap = StrokeCap.Butt,
                pathEffect = PathEffect.dashPathEffect(floatArrayOf(dashSize, gapSize))
            )
        )
    }
)


@Composable
fun Modifier.gradientUnderline(
    colors: List<Color> = listOf(Color.Red, Color.Yellow, Color.Green),
    thickness: Dp = 2.dp,
    paddingBottom: Dp = 4.dp
): Modifier = this.then(
    drawBehind {
        val strokeWidth = thickness.toPx()
        val y = size.height - paddingBottom.toPx()

        drawLine(
            brush = Brush.horizontalGradient(colors),
            start = Offset(0f, y),
            end = Offset(size.width, y),
            strokeWidth = strokeWidth,
            cap = StrokeCap.Round
        )
    }
)


@Composable
fun Modifier.animatedUnderlineInfinity(
    start: Boolean,
    color: Color = MaterialTheme.colorScheme.tertiary,
    thickness: Dp = 2.dp,
    paddingBottom: Dp = 1.dp,
    speed: Int = 1200
): Modifier = composed {

    val infiniteTransition = rememberInfiniteTransition(label = "underline_anim")

    val progress by infiniteTransition.animateFloat(
        initialValue = 0f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(
            animation = tween(durationMillis = speed),
            repeatMode = RepeatMode.Restart
        ),
        label = "underline_progress"
    )

    val density = LocalDensity.current
    val thicknessPx = with(density) { thickness.toPx() }
    val paddingPx = with(density) { paddingBottom.toPx() }

    drawBehind {

        if (!start) return@drawBehind

        val segmentWidth = size.width * 0.1f
        val totalWidth = size.width

        val x = totalWidth * progress - segmentWidth
        val y = size.height - paddingPx

        drawLine(
            color = color,
            start = Offset(x, y),
            end = Offset(x + segmentWidth, y),
            strokeWidth = thicknessPx,
            cap = StrokeCap.Round
        )
    }
}


@Composable
fun Modifier.wavyUnderline(
    color: Color = Color.Black,
    thickness: Dp = 1.dp,
    waveHeight: Dp = 2.dp,
    waveLength: Dp = 16.dp,
    paddingBottom: Dp = 6.dp
): Modifier = this.then(
    drawBehind {
        val strokeWidth = thickness.toPx()
        val amplitude = waveHeight.toPx()
        val wavelength = waveLength.toPx()
        val baseY = size.height - paddingBottom.toPx()

        val path = Path()
        path.moveTo(0f, baseY)

        var x = 0f
        while (x < size.width) {
            val endX = minOf(x + wavelength / 2, size.width)
            val controlX = x + wavelength / 4
            val controlY = baseY - amplitude

            path.quadraticTo(controlX, controlY, endX, baseY)
            x = endX
        }

        drawPath(
            path = path,
            color = color,
            style = Stroke(
                width = strokeWidth,
                cap = StrokeCap.Round
            )
        )
    }
)


@Composable
fun Modifier.doubleUnderline(
    color: Color = Color.Black,
    thickness: Dp = 1.dp,
    spacing: Dp = 4.dp,
    paddingBottom: Dp = 4.dp
): Modifier = this.then(
    drawBehind {
        val strokeWidth = thickness.toPx()
        val spacingPx = spacing.toPx()
        val y1 = size.height - paddingBottom.toPx()
        val y2 = y1 + spacingPx

        // First line
        drawLine(
            color = color,
            start = Offset(0f, y1),
            end = Offset(size.width, y1),
            strokeWidth = strokeWidth
        )

        // Second line
        drawLine(
            color = color,
            start = Offset(0f, y2),
            end = Offset(size.width, y2),
            strokeWidth = strokeWidth
        )
    }
)

@Composable
fun Modifier.underlineIf(
    condition: Boolean,
    color: Color = Color.Black,
    defaultColor: Color = Color.Unspecified,
    thickness: Dp = 1.dp,
    paddingBottom: Dp = 4.dp
): Modifier = this.then(
    drawBehind {
        val col = if (condition) color else defaultColor
        val strokeWidth = thickness.toPx()
        val y = size.height + paddingBottom.toPx()

        drawLine(
            color = col,
            start = Offset(0f, y),
            end = Offset(size.width, y),
            strokeWidth = strokeWidth
        )
    }
)


@Composable
fun Modifier.displayShimmer(
    colors: List<Color>,
    speed: Int
): Modifier = composed {
    val transition = rememberInfiniteTransition()
    val translateAnim = transition.animateFloat(
        initialValue = 0f,
        targetValue = 1000f,
        animationSpec = infiniteRepeatable(
            animation = tween(
                durationMillis = speed,
                easing = LinearEasing
            )
        )
    )

    val brush = Brush.linearGradient(
        colors = colors,
        start = Offset.Zero,
        end = Offset(x = translateAnim.value, y = translateAnim.value)
    )

    this.background(brush)
}

fun Modifier.shimmerProgress(
    progress: Float,
    color: Color = Color.LightGray,
    shimmerColor: Color = Color.White.copy(alpha = 0.6f),
    backgroundColor: Color = color.copy(alpha = 0.2f),
    cornerRadius: Dp = 4.dp
): Modifier = composed {
    // 1. Setup the infinite animation for the shimmer offset
    val transition = rememberInfiniteTransition(label = "shimmer")
    val translateAnim by transition.animateFloat(
        initialValue = 0f,
        targetValue = 1000f,
        animationSpec = infiniteRepeatable(
            animation = tween(1200, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = "shimmerTranslation"
    )

    this.drawWithContent {
        val width = size.width
        val height = size.height
        val radiusPx = cornerRadius.toPx()

        // 2. Draw Background Track
        drawRoundRect(
            color = backgroundColor,
            size = size,
            cornerRadius = CornerRadius(radiusPx)
        )

        // 3. Create Shimmer Brush
        // The brush moves based on the animated translation value
        val brush = Brush.linearGradient(
            colors = listOf(color, shimmerColor, color),
            start = Offset(translateAnim - 300f, 0f),
            end = Offset(translateAnim, 0f),
            tileMode = TileMode.Clamp
        )

        // 4. Draw Progress Bar with Shimmer
        drawRoundRect(
            brush = brush,
            size = size.copy(width = width * progress.coerceIn(0f, 1f)),
            cornerRadius = CornerRadius(radiusPx)
        )
    }
}

fun Modifier.shimmerProgress(
    progress: Float,
    colors: List<Color>,
    speed: Int,
    backgroundColor: Color,
): Modifier = composed {
    val infiniteTransition = rememberInfiniteTransition()
    val shimmerPosition = infiniteTransition.animateFloat(
        initialValue = -0.5f,
        targetValue = 1.5f,
        animationSpec = infiniteRepeatable(
            animation = tween(speed, easing = LinearEasing)
        )
    )

    drawWithContent {
        drawContent()

        val width = size.width
        val height = size.height
        val progressWidth = width * progress.coerceIn(0f, 1f)
        val shimmerStart = width * shimmerPosition.value - (width * 0.2f)
        val shimmerEnd = shimmerStart + (width * 0.4f)

        // Only draw shimmer if there's progress to show
        if (progressWidth > 0) {
            val brush = Brush.horizontalGradient(
                colors = colors,
                startX = shimmerStart,
                endX = shimmerEnd
            )

            drawRect(
                brush = brush,
                topLeft = Offset(0f, 0f),
                size = size.copy(progressWidth)//  Size(progressWidth, height)
            )
        }

        // Draw unfilled background
//        if (progress < 1f) {
//            drawRect(
//                color = backgroundColor,
//                topLeft = Offset(progressWidth, 0f),
//                size = size.copy(width - progressWidth)
//            )
//        }
        // 2. Draw Background Track
        drawRoundRect(
            color = backgroundColor,
            size = size,
        )
    }
}