package api.auth.kimdeo

import api.auth.kimdeo.core.MediaState
import api.auth.kimdeo.core.VideoInteraction
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import org.w3c.dom.HTMLVideoElement

class VideoController : VideoInteraction {

    private val _state = MutableStateFlow(MediaState())

    override val state: StateFlow<MediaState> = _state.asStateFlow()

    private var video: HTMLVideoElement? = null

    fun attach(video: HTMLVideoElement) {
        this.video = video

        fun updateState() {
            _state.value = MediaState(
                currentTime = video.currentTime,
                duration = if (video.duration.isNaN()) 0.0 else video.duration,
                isPlaying = !video.paused,
                volume = video.volume
            )
        }

        video.ontimeupdate = {
            updateState()
            null
        }

        video.onplaying = {
            updateState()
            null
        }

        video.onpause = {
            updateState()
            null
        }

        video.onvolumechange = {
            updateState()
            null
        }

        video.onloadedmetadata = {
            updateState()
            null
        }
    }

    override fun stop() {
        video?.apply {
            pause()
            currentTime = 0.0
        }
    }

    override fun play() {
        video?.play()
    }

    override fun pause() {
        video?.pause()
    }

    override fun seek(time: Double) {
        video?.currentTime = time
    }

    override fun setVolume(volume: Double) {
        video?.volume = volume
    }
}