    suspend fun uploadProfileImage(
        email: String,
        bytes: ByteArray,
        mimeType: String,
        fileName: String,
//        file: PlatformFile,
        onFileUpload: (byteSent: Long, byteSize: Long?) -> Unit,
    ): ResponseMessage<UserModel> {
        val res = apiClient.submitFormWithBinaryData(
            url = "$API_ROOT_PATH/users/upload-profile-file/${email}",
            formData = formData {
                append(
                    "file",
                    bytes,
                    Headers.build {
                        append(
                            HttpHeaders.ContentDisposition,
                            "form-data; name=\"file\"; filename=\"$fileName\""
                        )
                        append(HttpHeaders.ContentType, mimeType)
                    }
                )
            },
        ) {
            val totalBytes = bytes.size.toLong()
            var lastProgress = 0L
            onUpload { bytesSentTotal, _ ->
                val progress = ((bytesSentTotal.toDouble() / totalBytes) * 100).toLong()

                if (progress != lastProgress) {
                    lastProgress = progress
                    onFileUpload(progress, totalBytes)
                }
            }
        }
        val resUser = kimJson.decodeFromString<ResponseMessage<UserModel>>(res.bodyAsText())
        return if (resUser.status) resUser
        else throw AuthenticationException(resUser.message)
    }


