    suspend fun createVoicePlayer(
        logInModel: LogInModel,
        bytes: ByteArray,
        mimeType: String,
        fileName: String,
        languageCode: String,
        onProgress: (Long) -> Unit
    ): ResponseMessage<TranscribeJobModel?> {

        val response = suspendCancellableCoroutine { cont ->
//                url = "${API_ROOT_PATH}/transcription/create_voice_player/$email",
            authUploadFile(
                url = "${API_ROOT_PATH}/transcription/create_voice_player",
                bytes = bytes,
                fileName = fileName,
                languageCode = languageCode,
                logInModelString = kimJson.encodeToString(logInModel),
                authToken = PreferenceManager.getInvokeLogin().token,// BuildConfig.API_AUTH_KEY,
                mimeType = mimeType,

                onProgress = {
                    onProgress(it)
                },

                onComplete = {
                    cont.resume(it)
                },

                onError = {
                    Logger.e { "Error 5 $it" }
                    cont.resumeWithException(Exception(it))
                }
            )
        }
        return kimJson.decodeFromString(response)
    }


