    suspend fun deleteJobByJobId(
        logInModel: LogInModel,
        jobId: String
    ): ResponseMessage<TranscribeJobModel> {
        if (jobId.isEmpty()) return ResponseMessage(
            data = null,
            message = "Job id is empty",
            status = false
        )
        val res = apiClient.post("${API_ROOT_PATH}/transcription/delete_job/$jobId") {
            header(HttpHeaders.ContentType, "application/json")
            setBody(logInModel)
        }
        val resData =
            kimJson.decodeFromString<ResponseMessage<TranscribeJobModel>>(res.bodyAsText())
        return if (resData.status) resData
        else
            throw AuthenticationException(resData.message)
    }

