actual class KimDeoFile actual constructor() {
    actual fun saveFileToDownload(fileName: String, data: String) {
        // 1. Create a Blob from the string data
        // We specify 'text/plain' as the default MIME type
        val blob = Blob(
            arrayOf(data),
            BlobPropertyBag(type = "text/plain;charset=utf-8")
        )

        // 2. Create a temporary Object URL for the blob
        val url = URL.createObjectURL(blob)

        // 3. Create a hidden 'a' element to trigger the download
        val link = document.createElement("a") as HTMLAnchorElement
        link.href = url
        link.download = fileName

        // 4. Append, click, and cleanup
        document.body?.appendChild(link)
        link.click()
        document.body?.removeChild(link)

        // 5. Release the URL memory
        URL.revokeObjectURL(url)
    }

    actual suspend fun saveBytesDownload(bytes: ByteArray, fileName: String) {
        // 1. Convert Kotlin ByteArray to JS Uint8Array
        val uint8Array = Uint8Array(bytes.size)
        bytes.forEachIndexed { index, byte ->
            uint8Array[index] = byte
        }

        // 2. Create a Blob from the data
        val blob = Blob(arrayOf(uint8Array), BlobPropertyBag(type = "application/octet-stream"))

        // 3. Create an Object URL for the Blob
        val url = URL.createObjectURL(blob)

        // 4. Create a hidden anchor element and trigger the download
        val link = document.createElement("a") as HTMLAnchorElement
        link.href = url
        link.download = fileName

        // Append to body, click, and remove
        document.body?.appendChild(link)
        link.click()
        document.body?.removeChild(link)

        // 5. Clean up the URL object to free memory
        URL.revokeObjectURL(url)
    }

}


actual fun uploadFile(
    url: String,
    bytes: ByteArray,
    fileName: String,
    languageCode: String,
    mimeType: String,
    authToken: String,
    onProgress: (Long) -> Unit,
    onComplete: (String) -> Unit,
    onError: (String) -> Unit
) {
    val xhr = XMLHttpRequest()

    // 1. Convert ByteArray to Uint8Array for JS compatibility
    val uint8Array = Uint8Array(bytes.size)
    bytes.forEachIndexed { index, byte -> uint8Array[index] = byte }

    // 2. Prepare the Multi-part Form Data
    val formData = FormData()
    // Create a Blob from the bytes to represent the file
    val blob = Blob(arrayOf(uint8Array), BlobPropertyBag(type = mimeType))
    formData.append("file", blob, fileName)
    formData.append("language", languageCode)

    // 3. Setup Progress Listener
    xhr.upload.onprogress = { event ->
        if (event.lengthComputable) {
            onProgress(event.loaded.toLong())
        }
    }

    // 4. Setup Completion/Error Listeners
    xhr.onload = {
        if (xhr.status in 200..299) {
            onComplete(xhr.responseText)
        } else {
            onError("Upload failed with status: ${xhr.status} ${xhr.statusText}")
        }
    }

    xhr.onerror = {
        onError("Network error occurred during upload.")
    }

    // 5. Open and Send
    xhr.open("POST", url, true)

    // Add Authorization if provided
    if (authToken.isNotEmpty()) {
        xhr.setRequestHeader("Authorization", "Bearer $authToken")
    }

    xhr.send(formData)
}


actual fun authUploadFile(
    url: String,
    bytes: ByteArray,
    fileName: String,
    languageCode: String,
    mimeType: String,
    logInModelString: String,
    authToken: String,
    onProgress: (Long) -> Unit,
    onComplete: (String) -> Unit,
    onError: (String) -> Unit
) {
    val xhr = XMLHttpRequest()

    // 1. FAST & CORRECT INTEROP: Cast directly to an Int8Array view, then access its buffer
    val jsArray = bytes.unsafeCast<Int8Array>()
    val blob = Blob(arrayOf(jsArray.buffer), BlobPropertyBag(type = mimeType))

    // 2. Prepare the Multi-part Form Data
    val formData = FormData()
    formData.append("file", blob, fileName)
    formData.append("language", languageCode)
    formData.append("login_model", logInModelString)

    // 3. Setup Progress Listener
    xhr.upload.onprogress = { event ->
        if (event.lengthComputable) {
            onProgress(event.loaded.toLong())
        }
    }

    // 4. Setup Completion/Error Listeners
    xhr.onload = {
        if (xhr.status in 200..299) {
            onComplete(xhr.responseText)
        } else {
            onError("Upload failed with status: ${xhr.status} ${xhr.statusText}")
        }
    }

    xhr.onerror = {
        onError("Network error occurred during upload.")
    }

    // 5. Open and Send
    xhr.open("POST", url, true)

    // Add Authorization if provided
    if (authToken.isNotEmpty()) {
        xhr.setRequestHeader("Authorization", "Bearer $authToken")
    }

    xhr.send(formData)
}


