    var lang: String
    var volume: Float
    var rate: Float
    var pitch: Float
}

external interface MySpeechSynthesis {
    fun speak(utterance: SpeechSynthesisUtterance)
    fun cancel()
    fun pause()
    fun resume()
}

// Add synthesis to the existing Window interface
inline val windowSpeechSynthesis: MySpeechSynthesis
    get() = window.asDynamic().speechSynthesis as MySpeechSynthesis

actual class SpeechSynthesis {
    actual fun speakText(text: String, codeCountry: String, volume: Double) {
        stopText()
        val utterance = SpeechSynthesisUtterance(text)
        utterance.lang = codeCountry
        utterance.volume = volume.coerceIn(0.0, 1.0).toFloat()

        windowSpeechSynthesis.speak(utterance)
    }

    actual fun stopText() {
        windowSpeechSynthesis.cancel()
    }
}


actual suspend fun generateThumbnail(
    bytes: ByteArray,
    mimeType: String
): String {

    val uint8Array =
        Uint8Array(bytes.size)

    bytes.forEachIndexed { index, byte ->
        uint8Array[index] = byte//.toInt().toShort()
    }

    val blob = Blob(
        arrayOf(uint8Array),
        BlobPropertyBag(type = mimeType)
    )

    val url =
        URL.createObjectURL(blob)

    val video =
        document
            .createElement("video")
                as HTMLVideoElement

    video.src = url

    Promise<Unit> { resolve, _ ->
        video.onloadedmetadata = {
            resolve(Unit)
        }
    }.await()

    video.currentTime = 1.0

    Promise<Unit> { resolve, _ ->
        video.onseeked = {
            resolve(Unit)
        }
    }.await()

    val canvas =
        document
            .createElement("canvas")
                as HTMLCanvasElement

    canvas.width = video.videoWidth
    canvas.height = video.videoHeight

    val ctx = canvas.getContext("2d")

    ctx.asDynamic().drawImage(video, 0, 0)

    val thumbnail =
        canvas.toDataURL("image/png")

    URL.revokeObjectURL(url)

    return thumbnail
}


private fun formatTime(seconds: Double): String {
    val m = (seconds / 60).toInt()
    val s = (seconds % 60).toInt()
    return "${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}"
}


@OptIn(ExperimentalComposeUiApi::class)
actual fun playAudio(
    bytes: ByteArray,
    volume: Double,
    mimeType: String,
    interaction: (AudioInteraction) -> Unit
) {
    val objectUrl = run {
        // Optimized: Create Uint8Array and copy bytes directly
        val uint8Array = Uint8Array(bytes.size)
        for (i in bytes.indices) {
            uint8Array[i] = bytes[i]
        }

        val blob = Blob(arrayOf(uint8Array), BlobPropertyBag(type = mimeType))
        URL.createObjectURL(blob)
    }

    val audio = (document.createElement("audio") as HTMLAudioElement).apply {
        src = objectUrl
        setAttribute("preload", "auto")
        this.volume = volume.coerceIn(0.0, 1.0)
    }
    val controller = object : AudioInteraction {
        private val _state = MutableStateFlow(MediaState(volume = audio.volume))
        override val state: StateFlow<MediaState> = _state.asStateFlow()

        init {
            audio.onloadedmetadata = {
                _state.update { it.copy(duration = audio.duration) }
            }

            audio.onplay = { _state.update { it.copy(isPlaying = true) } }
            audio.onpause = { _state.update { it.copy(isPlaying = false) } }

            audio.ontimeupdate = {
                _state.update { it.copy(currentTime = audio.currentTime) }
            }

            // Sync volume changes back to state (e.g. if muted by system)
            audio.onvolumechange = {
                _state.update { it.copy(volume = audio.volume) }
            }

            audio.onended = {
                _state.update { it.copy(isPlaying = false, currentTime = 0.0) }
            }
        }

        override fun stop() {
            audio.pause()
            audio.currentTime = 0.0
        }

        override fun play() {
            audio.play().catch {
                console.error("Autoplay blocked or playback failed: ", it)
            }
        }

        override fun pause() {
            audio.pause()
        }

        override fun seek(time: Double) {
            audio.currentTime = time
        }

        override fun setVolume(volume: Double) {
            val clampedVolume = volume.coerceIn(0.0, 1.0)
            audio.volume = clampedVolume
            // State will be updated via the onvolumechange listener
        }
    }

    interaction(controller)
    controller.play()
}


actual fun loadHiddenVideoMetadata(
    bytes: ByteArray,
    mimeType: String,
    onReady: (VideoInteraction) -> Unit
): Disposable {
    // 1. Setup Resource
    val blob = Blob(
        arrayOf(Int8Array(bytes.toTypedArray()).buffer),
        BlobPropertyBag(type = mimeType)
    )
    val url = URL.createObjectURL(blob)
    val video = document.createElement("video") as HTMLVideoElement

    // 2. Configure Video
    video.style.display = "none"
    video.preload = "metadata"
    video.src = url
    document.body?.appendChild(video)

    val stateFlow = MutableStateFlow(MediaState())

    val interaction = object : VideoInteraction {
        override val state: StateFlow<MediaState> get() = stateFlow
        override fun stop() {
            video.pause(); video.currentTime = 0.0
        }

        override fun play() {
            video.play()
        }

        override fun pause() {
            video.pause()
        }

        override fun seek(time: Double) {
            video.currentTime = time
        }

        override fun setVolume(volume: Double) {
            video.volume = volume.coerceIn(0.0, 1.0)
        }
    }

    // 3. Define Listeners
    val metadataListener: (Event) -> Unit = {
        stateFlow.value = MediaState(
            currentTime = video.currentTime,
            duration = video.duration,
            isPlaying = !video.paused
        )
        onReady(interaction)
    }

    video.addEventListener("loadedmetadata", metadataListener)

    // 4. Return Cleanup Handle
    return object : Disposable {
        override fun dispose() {
            video.removeEventListener("loadedmetadata", metadataListener)
            video.pause()
            video.remove()
            URL.revokeObjectURL(url)
        }
    }
}


