    val endedListener: (Event) -> Unit = { updateState() }

    audio.addEventListener("loadedmetadata", metadataListener)
    audio.addEventListener("play", playListener)
    audio.addEventListener("pause", pauseListener)
    audio.addEventListener("ended", endedListener) // Triggers when audio hits the end

// 4. Return Cleanup Handle (Make sure to clean up the new listeners!)
    return object : Disposable {
        override fun dispose() {
            audio.removeEventListener("loadedmetadata", metadataListener)
            audio.removeEventListener("play", playListener)
            audio.removeEventListener("pause", pauseListener)
            audio.removeEventListener("ended", endedListener)
            audio.pause()
            audio.remove()
            URL.revokeObjectURL(url)
        }
    }
