@OptIn(ExperimentalComposeUiApi::class)
@Composable
actual fun VideoPlayer(
    modifier: Modifier,
    platformFile: PlatformFile,
//    bytes: ByteArray,
    mimeType: String,
    onVolume: (Int) -> Unit,
    onBack: () -> Unit,
    onForwardClicked: () -> Unit,
    onBackwardClicked: () -> Unit,
    interaction: (VideoInteraction) -> Unit
) {
//    val objectUrl = remember(bytes) {
//        val uint8Array = Uint8Array(bytes.toTypedArray())
//        val blob = Blob(arrayOf(uint8Array), BlobPropertyBag(type = mimeType))
//        URL.createObjectURL(blob)
//    }

    val controller = remember { VideoController() }
    val uiState by controller.state.collectAsState()

    val container = remember {
        val root = document.createElement("div") as HTMLDivElement
        root.style.apply {
            position = "relative"
            width = "100%"
            height = "100%"
            background = "black"
            asDynamic().overflow = "hidden"
        }

        // --- ENFORCE VIDEO TO OCCUPY WHOLE CONTAINER ---
        val video = document.createElement("video") as HTMLVideoElement
        video.src = URL.createObjectURL(platformFile.file)// platformFile.file  objectUrl
        video.style.apply {
            width = "100%"
            height = "100%"
            objectFit = "contain" // Keeps aspect ratio, use "cover" if you want full crop fill
            asDynamic().transition = "transform 0.3s ease, width 0.3s ease, height 0.3s ease"
        }
        controller.attach(video)
        // --- CONTROLS OVERLAY CONTAINER ---
        val controlsContainer = document.createElement("div") as HTMLDivElement
        controlsContainer.style.apply {
            position = "absolute"
            top = "0"; left = "0"
            width = "100%"; height = "100%"
            asDynamic().pointerEvents = "none" // Let clicks pass through to root if needed
            zIndex = "1000"
            asDynamic().transition = "transform 0.3s ease, width 0.3s ease, height 0.3s ease"
        }

        // --- HUD & CONTROLS ---
        val timeHud = document.createElement("div") as HTMLDivElement
        timeHud.style.apply {
            position = "absolute"; top = "12px"; left = "12px"; padding = "6px 10px"
            borderRadius = "8px"; background = "rgba(0,0,0,0.6)"; color = "white"
            fontSize = "14px"; fontFamily = "monospace"; zIndex = "1000"
            transition = "opacity 0.2s ease"
        }

        // 1. VERTICAL TRACKED VOLUME (Right Side)
        val trackedVolContainer = document.createElement("div") as HTMLDivElement
        trackedVolContainer.style.apply {
            position = "absolute"; right = "16px"; top = "50%"
            transform = "translateY(-50%)"; display = "flex"; flexDirection = "column"
            alignItems = "center"; asDynamic().gap = "6px"; padding = "14px 10px"
            borderRadius = "16px"; background = "rgba(0,0,0,0.6)"; zIndex = "1000"
            transition = "opacity 0.2s ease"
        }
        val trackedVolSlider = (document.createElement("input") as HTMLInputElement).apply {
            type = "range"; min = "0"; max = "10"; value = "10"
            style.apply {
                width = "20px"; height = "120px"; asDynamic().writingMode = "vertical-lr"
            }
            oninput = { onVolume(value.toInt()); null }
        }
        trackedVolContainer.appendChild(trackedVolSlider)

        // 2. BOTTOM CONTROL BAR
        val bottomBar = document.createElement("div") as HTMLDivElement
        bottomBar.style.apply {
            position = "absolute"; left = "0"; right = "0"; bottom = "0"
            padding = "16px"; display = "flex"; flexDirection = "column"
            asDynamic().gap = "12px"; background = "linear-gradient(transparent, rgba(0,0,0,0.85))"
            zIndex = "1000"
            transition = "opacity 0.2s ease"
        }

        val seekBar = (document.createElement("input") as HTMLInputElement).apply {
            type = "range"; style.width = "100%"
            oninput = {
                if (!video.duration.isNaN()) video.currentTime =
                    (value.toDouble() / 100.0) * video.duration; null
            }
        }

        val row = document.createElement("div") as HTMLDivElement
        row.style.apply {
            display = "flex"; alignItems = "center"; justifyContent = "space-between"
        }

        // Playback Buttons helper
        fun btn(txt: String, onClick: () -> Unit) =
            (document.createElement("button") as HTMLButtonElement).apply {
                innerText = txt; style.apply {
                padding = "8px 12px"; color = "white"; background =
                "rgba(255,255,255,0.2)"; border = "none"; borderRadius = "20px"; cursor = "pointer"
            }
                onclick = { onClick(); null }
            }

        val playBtn = btn("▶") {
            if (video.paused) video.play().catch { console.error(it) } else video.pause()
        }

        val playbackControls = document.createElement("div") as HTMLDivElement
        playbackControls.style.display = "flex"
        playbackControls.style.asDynamic().gap = "8px"
        playbackControls.append(
            btn("❌") { onBack() },
            btn("⏪") {
                video.currentTime -= 10
                onBackwardClicked()
            },
            playBtn,
            btn("⏩") {
                video.currentTime += 10
                onForwardClicked()
            }
        )

        // 3. NATIVE MEDIA VOLUME & ROTATE/TOGGLE RATIO GROUP (Bottom Right)
        val rightSideControls = document.createElement("div") as HTMLDivElement
        rightSideControls.style.apply {
            display = "flex"; alignItems = "center"; asDynamic().gap = "12px"
        }

        val nativeVolGroup = document.createElement("div") as HTMLDivElement
        nativeVolGroup.style.apply {
            position = "absolute"
            left = "16px"
            top = "50%"
            transform = "translateY(-50%)"
            display = "flex"
            flexDirection = "column" // Stacks items vertically
            alignItems = "center"
            asDynamic().gap = "6px"
            padding = "14px 10px"
            borderRadius = "16px"
            background = "rgba(0,0,0,0.6)"
            zIndex = "1000"
            transition = "opacity 0.2s ease"
        }
        val volIcon = document.createElement("span") as HTMLSpanElement
        volIcon.apply { innerText = "🔊"; style.color = "white" }
        val nativeVolSlider = (document.createElement("input") as HTMLInputElement).apply {
            type = "range"; min = "0"; max = "100"; value = "100"
            style.apply {
                width = "20px"                  // Narrow width
                height = "120px"                // Tall height
                asDynamic().writingMode = "vertical-lr" // Forces native vertical slider
            }
            oninput = { video.volume = value.toDouble() / 100.0; null }
        }
        nativeVolGroup.append(volIcon, nativeVolSlider)
        var isLandscape = false
        val toggleSizeBtn = btn("🔄") {
            isLandscape = !isLandscape

            if (isLandscape) {
                val targetTransform = "translate(-50%, -50%) rotate(90deg)"
                val targetWidth = "${root.clientHeight}px"
                val targetHeight = "${root.clientWidth}px"

                // Rotate Video
                video.style.apply {
                    position = "absolute"; top = "50%"; left = "50%"
                    transform = targetTransform
                    width = targetWidth; height = targetHeight
                }

                // Rotate Controls alongside it
                controlsContainer.style.apply {
                    position = "absolute"; top = "50%"; left = "50%"
                    transform = targetTransform
                    width = targetWidth; height = targetHeight
                }
            } else {
                // Reset Video - Keep absolute centering properties clear but functional
                video.style.apply {
                    position = "absolute"; top = "0"; left = "0"
                    transform = "rotate(0deg)"
                    width = "100%"; height = "100%"
                }

                // Reset Controls - Use absolute coordinates so 100% bounds scale smoothly
                controlsContainer.style.apply {
                    position = "absolute"; top = "0"; left = "0"
                    transform = "rotate(0deg)"
                    width = "100%"; height = "100%"
                }
            }
        }
        toggleSizeBtn.title = "Rotate Video"

//        rightSideControls.append(nativeVolGroup, toggleSizeBtn)
        rightSideControls.append(toggleSizeBtn)

        row.append(playbackControls, rightSideControls)
        bottomBar.append(seekBar, row)
        // Update your root append line:
        // Append UI layers to the controls container instead of root
        controlsContainer.append(timeHud, trackedVolContainer, bottomBar, nativeVolGroup)

// Append only the video and the controls container to the root
        root.append(video, controlsContainer)
// --- SMART CONTROLS AUTO-HIDE & INTERACTION LOGIC ---
        var controlsVisible = true
        var hideTimeoutId: Int? = null

        fun updateControlsVisibility(visible: Boolean) {
            controlsVisible = visible

            // Toggle the entire parent layer instead of individual child arrays
            controlsContainer.style.opacity = if (visible) "1" else "0"
            controlsContainer.style.setProperty("pointer-events", if (visible) "auto" else "none")
        }

        fun startHideTimer() {
            hideTimeoutId?.let { window.clearTimeout(it) }
            hideTimeoutId = window.setTimeout({
                updateControlsVisibility(false)
            }, 3000)
        }

        root.addEventListener("click", { event: Event ->
            val target = event.target

            // If we click the video background, the root wrapper, or the empty space of the container
            if (target == video || target == root || target == controlsContainer) {
                if (controlsVisible) {
                    updateControlsVisibility(false)
                    hideTimeoutId?.let { window.clearTimeout(it) }
                } else {
                    updateControlsVisibility(true)
                    startHideTimer()
                }
            } else {
                // User clicked a functional control button inside the HUD, reset the hide timeout
                if (controlsVisible) startHideTimer()
            }
        })
        // Initialize display rules
        startHideTimer()

        VideoPlayerContainer(
            htmlRoot = root,
            htmlVideo = video,
            htmlPlayPauseBtn = playBtn,
            htmlTimeHud = timeHud,
            htmlSeekbar = seekBar
        )
    }

    LaunchedEffect(Unit) {
        interaction(controller)
    }

    container.htmlTimeHud.innerText =
        "${formatTime(uiState.currentTime)} / ${formatTime(uiState.duration)}"
    container.htmlSeekbar.value = ((uiState.currentTime / uiState.duration) * 100).toString()

    LaunchedEffect(uiState.isPlaying) {
        container.htmlPlayPauseBtn.innerText = if (uiState.isPlaying) "⏸" else "▶"
    }

    WebElementView(factory = { container.htmlRoot }, modifier = modifier)
}

@JsName("window")
external object BrowserWindow {
    fun signInWithGoogle(): Promise<String>
    fun signOutWithGoogle(): Promise<String>
}

actual fun getThirdPartyAuth(): ThirdPartyAuth {
    return object : ThirdPartyAuth {
        override suspend fun signInWithGoogle(): String {
            return BrowserWindow.signInWithGoogle().await()
        }

        override suspend fun signOutWithGoogle(): String {
            return BrowserWindow.signOutWithGoogle().await()
        }

    }
}