object SettingScreenModel : ScreenModel {


    var settingScreenType by mutableStateOf(SettingScreenType.BILLING)

    //    var planInterval by mutableStateOf(PlanInterval.MONTHLY)
    var openWebUrl by mutableStateOf<String?>(null)

    // account setting part
    var firstName by mutableStateOf("")
    var currentPassword by mutableStateOf("")
    var newPassword by mutableStateOf("")
    var confirmNewPassword by mutableStateOf("")
    var lastName by mutableStateOf("")
    var email by mutableStateOf("")
    var phoneNumber by mutableStateOf("")
    var dateOfBirth by mutableStateOf("")
    var roleTitle by mutableStateOf("")

    //    var settingPopupType by mutableStateOf<SettingPopupType>(SettingPopupType.InitialSetup)
//        private set
    var settingPopup by mutableStateOf(PopupModel())
        private set

    //    var confirmationPopupType by mutableStateOf(ConfirmationPopupType.NONE)
//        private set
    var confirmationPopup by mutableStateOf(ConfirmPopupModel())
        private set


    lateinit var userModel: UserModel
    var userImage: ByteArray? by mutableStateOf(null)
    private var userImagePlatformFile: PlatformFile? = null
    var connectionState by mutableStateOf<ConnectionState>(ConnectionState.None)
    var subscriptionPlans: List<PlanModel> by mutableStateOf(listOf())
    var planInterval by mutableStateOf(PlanInterval.MONTHLY)

    fun initializeScreenModel() {
        settingPopup = PopupModel()
        confirmationPopup = ConfirmPopupModel()
        connectionState = ConnectionState.None
        screenModelScope.launch {
            val userToken = PreferenceManager.getUserToken()
            connectionState = ConnectionState.OnLoading
            if (userToken == null) {
                connectionState =
                    ConnectionState.OnFailure("You are not logged in, please login to continue")
            } else {
                val u = ApiActions.getUserModelByEmail(
                    LogInModel(
                        userToken.email,
                        userToken.password
                    )
                )

                if (u.data == null) {
                    connectionState =
                        ConnectionState.OnFailure("Could not get your details, please try logging in to continue")
                    return@launch
                }
                ApiActions.getSubscriptionPlans(LogInModel(u.data.email, u.data.password)).apply {
                    subscriptionPlans =
                        data ?: listOf(ONE_TIME_PLAN, BONUS_PLAN, MONTHLY_PLAN, YEARLY_PLAN)
                }
                userModel = u.data
                firstName = u.data.firstName
                lastName = u.data.lastName
                email = u.data.email
                phoneNumber = u.data.phoneNumber
                dateOfBirth = u.data.dateOfBirth
                roleTitle = u.data.role
                connectionState = ConnectionState.OnSucsess("")
                if (userModel.imagePath.isNotEmpty()) {
                    userImage = ApiActionsFile.loadFile(
                        LoadFileRequest(
                            userModel.imagePath,
                            LogInModel(userModel.userId, userModel.password)
                        )
                    )
                }
            }
        }
    }

    fun selectImage() {
        screenModelScope.launch {
            // Pick an image file
            userImagePlatformFile = FileKit.openFilePicker(type = FileKitType.Image)
            userImage = userImagePlatformFile?.readBytes()
        }
    }


    fun paymentPlan(plnInterval: PlanInterval, urlString: (String?) -> Unit) {
        screenModelScope.launch {
            showPopup(
                PopupModel(
                    show = true,
                    title = "Payment Plan",
                    description = "Please want while your plan is been setup",
                    isDismissible = false,
                    content = { CircularProgressIndicator(Modifier.size(PixelDensity.LARGE)) })
            )
            when (plnInterval) {
                PlanInterval.ONE_TIME -> {
                    runCatching {
                        ApiActions.oneTimePay(
                            PayStackInitTransaction(
                                email = userModel.email,
                                amount = (planInterval.amount * 100 * userModel.country.amountToNaira).toString(),
                                plan = planInterval.planCode,
                                referenceId = Tools.generateUUID(
                                    uuidStrength = UuidStrength.MEDIUM
                                )

                            )
                        )
                    }.onSuccess { d ->
                        if (d.status == true) {
                            urlString(d.data?.authorizationUrl)
                            dismissPopups()
                            dismissConfirmPopup()
                        } else {
                            showPopup(
                                PopupModel(
                                    show = true,
                                    title = "Payment Error",
                                    description = "Please try again later, there was an error",
                                )
                            )
                        }
                    }.onFailure {
                        showPopup(
                            PopupModel(
                                show = true,
                                title = "Payment Error",
                                description = "Please try again later, there was an error",
                            )
                        )
                    }
                }

                PlanInterval.BONUS_PLAN -> {
                    runCatching {
                        ApiActions.oneTimePay(
                            PayStackInitTransaction(
                                email = userModel.email,
                                amount = (planInterval.amount * 100 * userModel.country.amountToNaira).toString(),
                                plan = planInterval.planCode,
                                referenceId = Tools.generateUUID(
                                    uuidStrength = UuidStrength.MEDIUM
                                )

                            )
                        )
                    }.onSuccess { d ->
                        if (d.status == true) {
                            urlString(d.data?.authorizationUrl)
                            dismissPopups()
                            dismissConfirmPopup()
                        } else {
                            showPopup(
                                PopupModel(
                                    show = true,
                                    title = "Payment Error",
                                    description = "Please try again later, there was an error",
                                )
                            )
                        }
                    }.onFailure {
                        showPopup(
                            PopupModel(
                                show = true,
                                title = "Payment Error",
                                description = "Please try again later, there was an error",
                            )
                        )
                    }
                }

                else -> {
                    runCatching {
                        ApiActions.subscriptionPay(
                            payStackInitTransaction = PayStackInitTransaction(
                                email = userModel.email,
                                plan = planInterval.planCode,
                                amount = (planInterval.amount * 100 * userModel.country.amountToNaira).toString(),
                                referenceId = Tools.generateUUID(
                                    uuidStrength = UuidStrength.MEDIUM
                                )
                            )
                        )
                    }.onSuccess { d ->
                        if (d.status == true) {
                            urlString(d.data?.authorizationUrl)
                            dismissPopups()
                            dismissConfirmPopup()
                        } else {
                            showPopup(
                                PopupModel(
                                    show = true,
                                    title = "Payment Error",
                                    description = "Please try again later, there was an error subscribing you",
                                )
                            )
                        }
                    }.onFailure {
                        showPopup(
                            PopupModel(
                                show = true,
                                title = "Payment Error",
                                description = "Please try again later, there was an error subscribing you",
                            )
                        )
                    }
                }
            }
        }
    }

    fun changePassword() {
        screenModelScope.launch {
            runCatching {
            }
            val validatePassword = currentPassword.isNotEmpty() &&
                    newPassword.isNotEmpty() &&
                    confirmNewPassword.isNotEmpty() &&
                    userModel.password == currentPassword &&
                    newPassword == confirmNewPassword
            if (!validatePassword) {
                showPopup(
                    PopupModel(
                        show = true,
                        title = "Error",
                        description = "Your password does not match, please try again",
                        content = { Icon(TablerIcons.AlertTriangle, null, tint = Color.Red) }
                    ))
            } else {
                runCatching {
                    showPopup(
                        PopupModel(
                            show = true,
                            title = "Updating Password",
                            description = "Please wait while we update your password",
                            content = { CircularProgressIndicator(Modifier.size(PixelDensity.LARGE)) }
                        ))
                    ApiActions.updateUserModelById(
                        userModel.copy(password = newPassword)
                    )
                }.onSuccess { u ->
                    userModel = u.data!!
                    showPopup(
                        PopupModel(
                            show = true,
                            title = "Success",
                            description = "Your password has been updated successfully",
                            content = { Icon(TablerIcons.Check, null, tint = Color.Green) }
                        ))
                }.onFailure {
                    showPopup(
                        PopupModel(
                            show = true,
                            title = "Error",
                            description = "Could not update your password, please try again",
                            content = {
                                Icon(
                                    TablerIcons.AlertTriangle,
                                    null,
                                    tint = Color.Red
                                )
                            }
                        ))
                }
            }
        }
    }

    fun deleteYourAccount() {
        screenModelScope.launch {
            showPopup(
                PopupModel(
                    show = true,
                    title = "Deleting User",
                    description = "Please wait while we delete your account",
                    content = { CircularProgressIndicator(Modifier.size(PixelDensity.LARGE)) }
                ))
            val u = ApiActions.deleteUserModelById(userModel.userId)
            if (u.data == null) {
                showPopup(
                    PopupModel(
                        show = true,
                        title = "Error",
                        description = "Could not delete your account, please try again",
                        content = { Icon(TablerIcons.AlertTriangle, null, tint = Color.Red) }
                    ))
            } else {
                showPopup(
                    PopupModel(
                        show = true,
                        title = "Success",
                        description = "Your account has been deleted successfully",
                        content = { Icon(TablerIcons.Check, null, tint = Color.Green) }
                    ))
            }
        }
    }

    fun updateUserProfileImage() {
        screenModelScope.launch {
            runCatching {
                showPopup(
                    PopupModel(
                        show = true,
                        title = "Update Profile Image",
                        description = "Please wait while updating your profile image.",
                        content = { CircularProgressIndicator(Modifier.size(PixelDensity.LARGE)) }
                    ))
                ApiActions.uploadProfileImage(
                    email = email,
                    bytes = userImagePlatformFile!!.readBytes(),
                    mimeType = userImagePlatformFile?.mimeType()?.toString()
                        ?: "application/octet-stream",
                    fileName = userImagePlatformFile!!.name,
                    onFileUpload = { sent, size -> },
                )
            }.onSuccess { res ->
                if (res.data != null) {
                    userModel = res.data
                    showPopup(
                        PopupModel(
                            show = true,
                            title = "Profile Image",
                            description = res.message,
                            content = { Icon(TablerIcons.Check, null, tint = Color.Green) }
                        ))
                } else {
                    showPopup(
                        PopupModel(
                            show = true,
                            title = "Error",
                            description = cleanError(
                                res.message,
                                " There was an error uploading profile image"
                            ),
                            content = { Icon(TablerIcons.AlertTriangle, null, tint = Color.Red) }
                        ))
                }
            }.onFailure { err ->
                showPopup(
                    PopupModel(
                        show = true,
                        title = "Error",
                        description = cleanError(
                            err.message,
                            " There was an error uploading profile image"
                        ),
                        content = { Icon(TablerIcons.AlertTriangle, null, tint = Color.Red) }
                    ))
            }
        }
    }

    fun updateUserProfile() {
        screenModelScope.launch {
            runCatching {
                showPopup(
                    PopupModel(
                        show = true,
                        title = "Updating Profile",
                        description = "Please wait while we update your profile",
                        content = { CircularProgressIndicator(Modifier.size(PixelDensity.LARGE)) }
                    ))
                val newUserModel = userModel.copy(
                    firstName = firstName,
                    lastName = lastName,
                    email = email,
                    phoneNumber = phoneNumber,
                    dateOfBirth = dateOfBirth,
                    role = roleTitle
                )
                ApiActions.updateUserModelById(newUserModel)
            }.onSuccess { u ->
                userModel = u.data!!
                showPopup(
                    PopupModel(
                        show = true,
                        title = "Success",
                        description = "Your details have been updated successfully",
                        content = { Icon(TablerIcons.Check, null, tint = Color.Green) }
                    ))

            }.onFailure {
                showPopup(
                    PopupModel(
                        show = true,
                        title = "Error",
                        description = "Could not update your details, please try again",
                        content = { Icon(TablerIcons.AlertTriangle, null, tint = Color.Red) }
                    ))
            }
        }
    }

    fun showPopup(pm: PopupModel) {
        confirmationPopup = ConfirmPopupModel()
        settingPopup = pm
    }

    fun showConfirmPopup(cpm: ConfirmPopupModel) {
        settingPopup = PopupModel()
        confirmationPopup = cpm
    }

    fun dismissPopups() {
        settingPopup = PopupModel()
    }

    fun dismissConfirmPopup() {
        confirmationPopup = ConfirmPopupModel()
    }
}