package api.auth.kimdeo.core

import api.auth.kimdeo.screens.ScreenType
import cafe.adriel.voyager.core.screen.Screen
import cafe.adriel.voyager.navigator.Navigator


fun Navigator.navigateTo(screen: Screen, screenType: ScreenType){
    this.push(screen)
    PreferenceManager.saveScreen(screenType)
}

fun Navigator.navigateBack(screenType: ScreenType){
    this.pop()
    PreferenceManager.saveScreen(screenType)
}

fun Navigator.navigateReplace(screen: Screen, screenType: ScreenType){
    this.replace(screen)
    PreferenceManager.saveScreen(screenType)
}
