package api.auth.kimdeo.core.api

import KimdeoAuth.composeApp.BuildConfig
import api.auth.kimdeo.createAuthHttpClient
import api.auth.kimdeo.createHttpClient
import api.auth.kimdeo.createNormalHttpClient
import api.auth.kimdeo.model.LoadFileRequest
import api.auth.kimdeo.model.RequestFilesModel
import api.auth.kimdeo.model.ResponseMessage
import api.auth.kimdeo.model.WebSocketJobModel
import api.auth.kimdeo.uploadFile
import api.auth.kimdeo.utils.cleanError
import co.touchlab.kermit.Logger
import io.ktor.client.request.header
import io.ktor.client.request.post
import io.ktor.client.request.setBody
import io.ktor.client.statement.bodyAsBytes
import io.ktor.client.statement.bodyAsText
import io.ktor.http.HttpHeaders
import io.ktor.http.isSuccess
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlinx.serialization.json.Json
import kotlin.coroutines.resume
import kotlin.coroutines.resumeWithException


object ApiActionsFile {
    private val kimJson = Json {
        prettyPrint = true
        isLenient = true
        classDiscriminator = "type"
        ignoreUnknownKeys = true
        explicitNulls = false
    }
    private val apiClient = createHttpClient()
    private val authApiClient = createAuthHttpClient()
    private val normalClient = createNormalHttpClient()


    suspend fun loadFile(loadFileRequest: LoadFileRequest): ByteArray? {
        try {
            val res = apiClient.post("$API_ROOT_PATH/file/load_up") {
//            header(HttpHeaders.Authorization, "Bearer ${payStackApi.secretKey}")

                header(HttpHeaders.ContentType, "application/json")
                setBody(loadFileRequest)
            }
            if (!res.status.isSuccess()) {
                throw Exception("Failed to download audio")
            }
            return res.bodyAsBytes()
        } catch (e: Exception) {
            return null
        }
    }


    suspend fun loadFileFree(filePath: String?): ByteArray? {
        try {
            val res = authApiClient.post("$API_ROOT_PATH/Z4cV6bN8mP2wR9tY3eH7") {
                header(HttpHeaders.ContentType, "application/json")
                setBody(mapOf("file_path" to filePath))
            }
            if (!res.status.isSuccess()) {
                throw Exception("Failed to download audio")
            }
            return res.bodyAsBytes()
        } catch (e: Exception) {
            return null
        }
    }

    suspend fun deleteSpecificFiles(
        requestFilesModel: RequestFilesModel
    ): ResponseMessage<String?> {
        try {
            val res = apiClient.post("$API_ROOT_PATH/file/delete_specific") {
                header(HttpHeaders.ContentType, "application/json")
                setBody(requestFilesModel)
            }
            if (!res.status.isSuccess()) {
                throw Exception("Failed to download audio")
            }
            return kimJson.decodeFromString<ResponseMessage<String?>>(res.bodyAsText())
        } catch (e: Exception) {
            return ResponseMessage(
                data = cleanError(e.message,"There was an error deleting the file. Please try again later."),
                message = "Can not delete file",
                status = false
            )
        }
    }

    suspend fun deleteSpecificFilesFree(
        filePath: List<String>?,
    ): ResponseMessage<String?> {
        if (filePath == null) ResponseMessage(
            data = null,
            message = "can not delete file at this time",
            status = false
        )
        try {
            val res = authApiClient.post("$API_ROOT_PATH/a7f3Xk9mQ2pL5vR8nB1d") {
                header(HttpHeaders.ContentType, "application/json")
                setBody(mapOf("file_paths" to filePath))
            }
            if (!res.status.isSuccess()) {
                throw Exception("Failed to download audio")
            }
            return kimJson.decodeFromString<ResponseMessage<String?>>(res.bodyAsText())
        } catch (e: Exception) {
            return ResponseMessage(
                data = cleanError(e.message,"There was an error deleting the file. Please try again later."),
                message = "Can not delete file",
                status = false
            )
        }
    }


    suspend fun downloadFile(loadFileRequest: LoadFileRequest): ByteArray {
        val res = apiClient.post("$API_ROOT_PATH/file/download") {
            header(HttpHeaders.ContentType, "application/json")
            setBody(loadFileRequest)
        }
        if (!res.status.isSuccess()) {
            throw Exception("Failed to download audio")
        }
        return res.bodyAsBytes()
    }

    // the string is audio path
    suspend fun uploadToPlayGround(
        bytes: ByteArray,
        folderUid:String,
        mimeType: String,
        fileName: String,
        languageCode: String = "en-US",
        onProgress: (Long) -> Unit
    ): WebSocketJobModel<String?> {
        val response = suspendCancellableCoroutine { cont ->
            uploadFile(
                url = "${API_ROOT_PATH}/upload_file_playground?folder-uid=$folderUid",
                bytes = bytes,
                fileName = fileName,
                authToken = BuildConfig.API_AUTH_KEY,
                mimeType = mimeType,
                languageCode = languageCode,
                onProgress = {
                    onProgress(it)
                },

                onComplete = {
                    cont.resume(it)
                },

                onError = {
                    Logger.e { "Error 5 $it" }
                    cont.resumeWithException(Exception(it))
                }
            )
        }
        return kimJson.decodeFromString(response)
    }
}