class PlayGroundViewModel : ScreenModel {
    override fun onDispose() {
        super.onDispose()
        audioController?.stop()
        videoController?.stop()
        videoPlayerDisposable?.dispose()
        audioPlayerDisposable?.dispose()
        CoroutineScope(Dispatchers.Default).launch {
            try {
                if (deleteFilePaths.isNotEmpty()) {
                    val responce = ApiActionsFile.deleteSpecificFilesFree(
                        deleteFilePaths
                    )
                }
            } catch (e: Exception) {
                Logger.e { "Clean up Exception $e" }
            }
        }
    }


    // This will hold our controller once the UI initializes
    var videoController: VideoInteraction? = null
        private set
    var audioController: AudioInteraction? = null
        private set
    var audioVolume = 1.0
    var videoPlayerDisposable: Disposable? = null
        private set
    var audioPlayerDisposable: Disposable? = null
    var playGroundPopup by mutableStateOf(PopupModel())

    //    var connectionState by mutableStateOf<ConnectionState>(ConnectionState.None)
//        private set
    var fileUploadState by mutableStateOf<FileConnectionState>(FileConnectionState.None)
        private set
    var connectionState by mutableStateOf<ConnectionState>(ConnectionState.None)
    private var upFolderUid = ""

    var transcribeProcess by mutableStateOf(Triple(0f, "", ""))
        private set
//    var transcribeJobModel: TranscribeJobModel? = null
//    private val _transcribeJobModels = mutableStateListOf<TranscribeJobModel>()
//    val transcribeJobModels: List<TranscribeJobModel> get() = _transcribeJobModels

    val audioFilePaths = mutableSetOf<FilePathModel>()
    var audioFilePath: FilePathModel? = null
    var audioPosition = 0
    var loadingNextAudio = false
        private set
    var lastSeekTime = 0.0
//    var audioFilePathNext: FilePathModel? = null

    var kimLanguage by mutableStateOf(KimLanguage.ENGLISH)
    private var _kimLanguages =
        mutableStateListOf<KimLanguage>().apply { addAll(KimLanguage.entries.shuffled().take(5)) }
    val kimLanguages: List<KimLanguage> get() = _kimLanguages

    var fileByteArray by mutableStateOf<ByteArray?>(null)
        private set
    var audioByteArray by mutableStateOf<ByteArray?>(null)
        private set

    //    private val delFilePath = mutableListOf<String>()
    var platformFile by mutableStateOf<PlatformFile?>(null)
    var enableButton by mutableStateOf(true)
        private set
    val deleteFilePaths = mutableListOf<String>()
    var isResetting by mutableStateOf(false)
        private set


    init {
        resetScreenModel()
    }

    fun resetScreenModel() {
        connectionState = ConnectionState.None
        isResetting = true
        videoController = null
        audioController = null
        videoPlayerDisposable = null
        audioPlayerDisposable = null
        playGroundPopup = PopupModel()
        audioFilePath = null
        audioPosition = 0
        fileUploadState = FileConnectionState.None
        loadingNextAudio = false
        lastSeekTime = 0.0
        kimLanguage = KimLanguage.ENGLISH
        fileByteArray = null
        audioByteArray = null
        platformFile = null
        isResetting = false
        enableButton = true

        transcribeProcess = Triple(0f, "", "")
    }

    fun attachVideoController(
        controller: VideoInteraction
    ) {
        videoController = controller
    }

    fun attachAudioController(
        controller: AudioInteraction
    ) {
        audioController = controller
        audioController?.setVolume(audioVolume)
    }

    fun checkKimLanguages(lang: String) {
        if (lang.isBlank()) {
            _kimLanguages.clear()
            _kimLanguages.addAll(KimLanguage.entries.shuffled().take(5))
            return
        }
        // 1. Calculate the new data first
        val filtered = KimLanguage.entries
            .filter {
                val name = it.name.lowercase()
                name.contains(lang.lowercase(), ignoreCase = true)
            }
            .shuffled()
            .take(5)

        // 2. Update the existing SnapshotStateList
        _kimLanguages.clear()
        _kimLanguages.addAll(filtered)
    }

    fun getMediaFile() {
        screenModelScope.launch(Dispatchers.Main) {
            platformFile = FileKit.openFilePicker(
                mode = FileKitMode.Single,
                type = FileKitType.File(ExportVideoFormat.entries.map { it.name.lowercase() }
                    .toSet())
            )
            if (platformFile != null) fileByteArray = platformFile?.readBytes()
        }
    }

    fun transcribeVideo() {
        screenModelScope.launch {
            fileUploadState = FileConnectionState.OnUploading
            val fileBytes = platformFile?.size()
            runCatching {
                enableButton = false
                ApiActionsFile.uploadToPlayGround(
                    fileName = platformFile!!.name,
                    bytes = platformFile!!.readBytes(),
                    folderUid = upFolderUid,
                    languageCode = kimLanguage.codeCountry,
                    mimeType = platformFile?.mimeType()?.toString() ?: "application/octet-stream",
                    onProgress = { sentByte ->
                        transcribeProcess = if (fileBytes == null) Triple(0f, "", "")
                        else Triple(
                            fileBytes.toPercentage(sentByte).toFloat(),
                            "uploading file ${
                                Tools.convertLongToReadableSize(sentByte).replace("b", "%")
                            } of ${
                                Tools.convertLongToReadableSize(platformFile!!.size())
                            }",
                            ""
                        )
                    }
                )
            }.onSuccess { response ->
                if (response.jobStatus == JobStatus.FAILED) {
                    transcribeProcess = Triple(
                        response.completePercent.toFloat(),
                        response.message,
                        ""
                    )
                    return@onSuccess
                }
                audioFilePaths.clear()
                ApiActionsWebsocket.uploadToPlayGroundWebSocket(
                    jobId = response.wsId,
                    onConnect = { wjm ->
                        transcribeProcess = Triple(
                            wjm.completePercent.toFloat(),
                            wjm.message,
                            ""
                        )
                        wjm.dataType?.let {
                            audioFilePaths.add(wjm.dataType)
                            deleteFilePaths.addAll(audioFilePaths.map { it.filePath ?: "" })
                        }
                        when (wjm.jobStatus) {
                            JobStatus.COMPLETED -> {
                                enableButton = true
                                val firstAudio = audioFilePaths.firstOrNull()
                                    ?: return@uploadToPlayGroundWebSocket

                                audioFilePath = firstAudio
                                if (upFolderUid.isEmpty()) {
                                    upFolderUid =
                                        audioFilePath?.filePath
                                            ?.replace("\\", "/")
                                            ?.split("/")
                                            ?.dropLast(1)
                                            ?.lastOrNull()
                                            ?: ""
                                }
                                launch {
                                    audioByteArray = ApiActionsFile.loadFileFree(
                                        audioFilePath?.filePath!!,
                                    )
                                }
                            }

                            JobStatus.FAILED -> {
                                enableButton = true
                                playGroundPopup = PopupModel(
                                    show = true,
                                    content = {
                                        Icon(
                                            TablerIcons.FileAlert,
                                            contentDescription = null,
                                            tint = Color.Red
                                        )
                                    },
                                    title = "Transcribe Error",
                                    description = wjm.message
                                )
                            }

                            else -> Unit
                        }
                    }
                )
            }.onFailure { error ->
                enableButton = true
                playGroundPopup = PopupModel(
                    show = true,
                    content = {
                        Icon(
                            TablerIcons.FileAlert,
                            contentDescription = null,
                            tint = Color.Red
                        )
                    },
                    title = "Transcription Error",
                    description = cleanError(
                        error.message,
                        "There was an error transcribing please try again later"
                    )
                )

            }
        }
    }

    @OptIn(ExperimentalCoroutinesApi::class)
    fun updatePlayingAudio(audioPos: FilePathModel? = null) {
        if (audioFilePath == null || audioByteArray == null) return
        screenModelScope.launch {
            loadingNextAudio = true
            if (audioPos == null) {
                audioPosition++
                audioFilePath = audioFilePaths.toList()[audioPosition]
            } else {
                audioFilePath = audioPos
            }
            audioController?.stop()
            audioPlayerDisposable?.dispose()
            audioByteArray = ApiActionsFile.loadFileFree(
                audioFilePath?.filePath!!,
            )
            audioPlayerDisposable = loadHiddenAudioMetadata(
                bytes = audioByteArray!!,
                mimeType = "audio/wav",
                onReady = { interaction ->
                    attachAudioController(interaction)
                }
            )

            ApiActionsWebsocket.connectToPlayingVideoWebsocketFree(
                onConnect = { fpm ->
                    fpm.dataType?.let {
                        audioFilePaths.add(it)
                        it.filePath?.let { element -> deleteFilePaths.add(element) }
                    }
                },
                genVoice = GenerateVoiceWVIPModelFree(
                    folderId = upFolderUid,
                    jsonFilePath = audioFilePath!!.transcriptionPath!!,
                    languageCode = kimLanguage.codeCountry,
                    startTime = audioFilePath!!.endTime
                )
            )
            loadingNextAudio = false
        }

    }

    fun onBackPressed() {
        CoroutineScope(Dispatchers.Default).launch {
            try {
                if (deleteFilePaths.isNotEmpty()) {
                    val responce = ApiActionsFile.deleteSpecificFilesFree(
                        deleteFilePaths
                    )
                }
            } catch (e: Exception) {
                Logger.e { "Clean up Exception $e" }
            }
        }
        resetScreenModel()
    }

    fun onWatchClicked() {
        connectionState = ConnectionState.OnLoading
    }

    fun onVideoBackPressed() {
        audioController?.stop()
        audioPlayerDisposable?.dispose()
        audioPosition = 0
    }
}