object KimdeoSelectVideoScreen : Screen {
    @Composable
    override fun Content() {
        val deviceInfo = rememberDeviceInfo()
        val screenModel =
            LocalNavigator.currentOrThrow.rememberNavigatorScreenModel { KimdeoSelectVideoScreenModel() }
        Scaffold(
            modifier = Modifier
                .fillMaxSize(),
            bottomBar = {
                if (deviceInfo.orientation == Orientation.PORTRAIT) {
                    TranscribeOutputPortrait(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(MaterialTheme.colorScheme.primaryContainer),
                        screenModel = screenModel
                    )
                }
            }, floatingActionButton = {
                if (deviceInfo.orientation == Orientation.PORTRAIT) {

                    SmallFloatingActionButton(
                        onClick = {
                            if (screenModel.selectedTranscribeJobModels.isNotEmpty()) {
                                screenModel.availableSubPopup = PopupModel(show = true)
                            }
                        },
                    ) {
                        Text(
                            modifier = Modifier.padding(horizontal = PixelDensity.SMALL),
                            text = "Subtitles",
                            style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                        )
                    }
                }
            }) { pv ->
            Box(
                Modifier.fillMaxSize().padding(pv),
                contentAlignment = Alignment.Center
            ) {
                when (screenModel.connectionState) {
                    is ConnectionState.OnFailure -> {
                        ShimmeringText(
                            shimmerColors = listOf(
                                MaterialTheme.colorScheme.error,
                                Color.Yellow,
                                MaterialTheme.colorScheme.onError,
                            ),
                            text = (screenModel.connectionState as ConnectionState.OnFailure).data
                        )
                    }

                    is ConnectionState.OnSucsess -> {
                        OnScreeModelSuccess()
                    }

                    else -> {
                        OnScreeModelInit(
                            Modifier.fillMaxSize().padding(pv),
                            screenModel = screenModel
                        )
                    }
                }
            }
        }
    }

    @Composable
    private fun OnScreeModelSuccess() {
        val deviceInfo = rememberDeviceInfo()
        when (deviceInfo.orientation) {
            Orientation.PORTRAIT -> SelectVideoFilePortrait(
                modifier = Modifier.fillMaxSize()
                    .padding(horizontal = PixelDensity.MEDIUM, vertical = PixelDensity.SMALL)
                    .verticalScrollable()
            )

            else -> SelectVideoFileLandscape(
                modifier = Modifier.fillMaxSize(),
            )
        }
    }

    @Composable
    private fun OnScreeModelInit(
        modifier: Modifier,
        screenModel: KimdeoSelectVideoScreenModel,
    ) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            val pulseBeforeShow = remember { mutableStateOf(false) }

            LaunchedEffect(pulseBeforeShow) {
                if (!pulseBeforeShow.value)
                    delay(5000.milliseconds)
                pulseBeforeShow.value = true
            }
            PulsingRing()
            if (pulseBeforeShow.value) {
                ShimmeringText(
                    "Loading... seems to be taking a lot of time.",
                    modifier = Modifier.padding(top = PixelDensity.LARGE),
                )
                ReloadButton(
                    modifier = Modifier.padding(top = PixelDensity.LARGE),
                    colors = listOf(
                        MaterialTheme.colorScheme.primary,
                        MaterialTheme.colorScheme.background
                    ),
                    onReload = {
                        screenModel.resetScreenModel()
                        pulseBeforeShow.value = false
                    },
                )
            }
        }
    }

    @Composable
    private fun KimPlayerPopup(screenModel: KimdeoSelectVideoScreenModel) {
        DisplayPopup(
            show = screenModel.displayTranscriptPopup.show,
            onDismiss = { screenModel.displayTranscriptPopup = PopupModel() },
            content = {
                Column(
                    modifier = Modifier.background(MaterialTheme.colorScheme.background)
                        .padding(PixelDensity.SMALL),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
                ) {
                    Text(
                        text = screenModel.displayTranscriptPopup.title,
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                    )
                    screenModel.displayTranscriptPopup.content()
                }
            }
        )
    }

    @Composable
    private fun TranscribeOutputPortrait(
        modifier: Modifier,
        screenModel: KimdeoSelectVideoScreenModel
    ) {
        Box(
            modifier,
            contentAlignment = Alignment.Center
        ) {
            Box(
                modifier = Modifier.fillMaxWidth()
                    .shimmerProgress(
                        color = MaterialTheme.colorScheme.primary,
                        shimmerColor = Color.Magenta,
                        progress = screenModel.transcribeProcess.first / 100
                    ).padding(PixelDensity.LARGE),
            )
            Text(
                text = screenModel.transcribeProcess.second.ifEmpty { "Transcription / Translation" },
                style = MaterialTheme.typography.bodyMedium.copy(
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.onBackground
                )
            )
        }
    }


    @Composable
    private fun SelectVideoFileLandscape(modifier: Modifier) {
        val navigator = LocalNavigator.currentOrThrow
        val screenModel = navigator.rememberNavigatorScreenModel { KimdeoSelectVideoScreenModel() }
        Row(modifier, horizontalArrangement = Arrangement.Center) {
            KimPlayerPopup(screenModel)
            LaunchedEffect(screenModel.audioByteArray) {
                if (screenModel.audioByteArray != null) {
                    screenModel.audioPlayerDisposable = loadHiddenAudioMetadata(
                        bytes = screenModel.audioByteArray!!,
                        mimeType = "audio/wav",
                        onReady = { interaction ->
                            screenModel.attachAudioController(interaction)
                        }
                    )
                }
            }
            Column(
                Modifier
                    .verticalScrollable(),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Row(
                    Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.Center,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    ElevatedCard(
                        modifier = Modifier.weight(1f).padding(PixelDensity.SMALL),
                    ) {
                        SelectFileCard(
                            modifier = Modifier.padding(PixelDensity.MEDIUM).fillMaxWidth(),
                            screenModel = screenModel
                        )
                    }
                    ElevatedCard(
                        modifier = Modifier.weight(1f).padding(PixelDensity.SMALL),
                    ) {
                        TranscribeFileCard(
                            modifier = Modifier.padding(PixelDensity.SMALL),
                            screenModel = screenModel,
                            nav = navigator
                        )
                    }
                }
                ElevatedCard(
                    modifier = Modifier.fillMaxWidth().padding(PixelDensity.SMALL),
                ) {
                    TranscribeOutput(
                        modifier = Modifier.padding(PixelDensity.SMALL).fillMaxWidth(),
                        screenModel = screenModel
                    )
                }
                AvailableSubtitles(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(PixelDensity.SMALL)
                        .outline(padding = PixelDensity.SMALL), screenModel
                )
            }
        }
    }

    @Composable
    private fun AvailableSubtitles(modifier: Modifier, screenModel: KimdeoSelectVideoScreenModel) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            Text(
                "Available Subtitles",
                style = MaterialTheme.typography.bodyLarge.copy(
                    fontWeight = FontWeight.Bold
                )
            )
            FlowRow(
                horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
            ) {
                for (tm in screenModel.selectedTranscribeJobModels.shuffled().take(5)) {

                    val subtitleName = tm.dataType.filePath.fileNameWithoutExtension()
                    ElevatedCard(Modifier.padding(PixelDensity.SMALL)) {
                        Column {
                            HorizontalTextIcon(
                                modifier = Modifier
                                    .clickable { screenModel.updateTranscribeModel(tm) }
                                    .outline(
                                        color = if (subtitleName == screenModel.transcribeJobModel?.filePath?.fileNameWithoutExtension()) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onBackground,
                                        width = PixelDensity.VERY_SMALL,
                                        padding = PixelDensity.MEDIUM
                                    ),
                                maxLines = 2,
                                style = MaterialTheme.typography.bodyMedium.copy(textAlign = TextAlign.Center),
                                leadingContent = {
                                    Text(
                                        text = tm.dataType.language.codeCountry.split("-").first()
                                            .uppercase(),
                                        style = MaterialTheme.typography.headlineSmall.copy(color = MaterialTheme.colorScheme.inversePrimary)
                                    )
                                },
                                text = subtitleName,
                                horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                                trailingContent = {
                                    Icon(
                                        if (tm.id == screenModel.selectedSubtitleId) TablerIcons.Checkbox else TablerIcons.Square,
                                        null
                                    )
                                }
                            )
                            Text(
                                Tools.formatTimestamp(tm.dataType.createdAt),
                                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                            )
                        }
                    }
                }
            }
        }
    }

    @Composable
    private fun SelectVideoFilePortrait(modifier: Modifier) {
        val navigator = LocalNavigator.currentOrThrow
        val screenModel = navigator.rememberNavigatorScreenModel { KimdeoSelectVideoScreenModel() }
        KimPlayerPopup(screenModel)
        DisplayPopup(
            show = screenModel.availableSubPopup.show,
            onDismiss = { screenModel.availableSubPopup = PopupModel() },
            content = {
                Box(
                    Modifier.fillMaxWidth(0.8f).background(MaterialTheme.colorScheme.background)
                        .padding(vertical = PixelDensity.EXTRA_LARGE).outline()
                ) {
                    AvailableSubtitles(
                        modifier = Modifier
                            .background(color = MaterialTheme.colorScheme.surfaceContainerLow)
                            .padding(PixelDensity.MEDIUM).verticalScrollable(),
                        screenModel = screenModel
                    )
                }
            }
        )
        Column(
            modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            ElevatedCard {
                SelectFileCard(
                    modifier = Modifier.fillMaxWidth().padding(PixelDensity.MEDIUM),
                    screenModel = screenModel
                )
            }
            ElevatedCard {
                TranscribeFileCard(
                    modifier = Modifier.fillMaxWidth().padding(PixelDensity.MEDIUM),
                    screenModel = screenModel,
                    nav = navigator
                )
            }
//        Button(
//            enabled = screenModel.selectedTranscribeJobModels.isNotEmpty(),
//            onClick = { screenModel.availableSubPopup = PopupModel(show = true) },
//        ) {
//            Text(
//                "Available Subtitles",
//                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
//            )
//        }
        }
    }


    @Composable
    private fun TranscribeFileCard(
        modifier: Modifier,
        screenModel: KimdeoSelectVideoScreenModel,
        nav: Navigator
    ) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            var selectedKimLanguage by remember { mutableStateOf("") }
            var expandLanguage by remember { mutableStateOf(false) }
            Text(
                text = "Configure Video",
                style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
            )
            OutlinedButton(
                modifier = Modifier.fillMaxWidth(),
                enabled = screenModel.fileByteArray != null && screenModel.enableButton,
                onClick = { expandLanguage = !expandLanguage },
                content = {
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        StyledText(
                            contents = listOf(
                                ComTextModel(
                                    text = "Select Language ",
                                    style = MaterialTheme.typography.bodyMedium.toSpanStyle()
                                ),
                                ComTextModel(
                                    text = "(${screenModel.kimLanguage})",
                                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                                        .toSpanStyle()
                                )
                            )
                        )
                        Icon(
                            if (expandLanguage) TablerIcons.ChevronUp else TablerIcons.ChevronDown,
                            contentDescription = "expand languages"
                        )
                    }
                })
            AnimatedVisibility(expandLanguage, content = {
                SelectLanguages(
                    selectedKimLanguage,
                    kimLanguage = screenModel.kimLanguage,
                    kimLanguages = screenModel.kimLanguages,
                    onLangNalChanged = {
                        selectedKimLanguage = it
                        screenModel.checkKimLanguages(it)
                    },
                    onClear = {
                        selectedKimLanguage = ""
                        screenModel.checkKimLanguages("")
                    },
                    onSelect = {
                        screenModel.kimLanguage = it
                        expandLanguage = !expandLanguage
                    }
                )
            })
            OutlinedButton(
                modifier = Modifier.fillMaxWidth(),
                enabled = screenModel.fileByteArray != null && screenModel.enableButton,
                onClick = { screenModel.transcribeVideo() },
                content = {
                    HorizontalTextIcon(
                        leadingContent = { Icon(TablerIcons.Stars, null) },
                        text = "Transcribe Video",
                        style = MaterialTheme.typography.bodyMedium
                    )
                })
            OutlinedButton(
                modifier = Modifier.fillMaxWidth(),
                enabled = screenModel.fileByteArray != null && screenModel.enableButton,
                onClick = {
                    screenModel.onWatchVideoClicked {
                        nav.navigateTo(KimdeoPlayVideoScreen, ScreenType.NONE)
                    }
                },
                content = {
                    HorizontalTextIcon(
                        leadingContent = { Icon(TablerIcons.Video, null) },
                        text = "Watch Video",
                        style = MaterialTheme.typography.bodyMedium
                    )
                })
        }
    }


    @Composable
    private fun SelectFileCard(modifier: Modifier, screenModel: KimdeoSelectVideoScreenModel) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            Column(
                Modifier
                    .outline()
                    .clickable(
                        onClick = { screenModel.getMediaFile() },
                        enabled = screenModel.enableButton
                    )
                    .padding(horizontal = PixelDensity.MEDIUM, vertical = PixelDensity.LARGE),
                verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                var thumbnail by remember {
                    mutableStateOf<String?>(null)
                }
                if (screenModel.fileByteArray == null) {
                    Icon(
                        contentDescription = null,
                        imageVector = TablerIcons.Folder,
                        modifier = Modifier.size(PixelDensity.getPixelDensity(100))
                    )
                    Text(
                        text = "Click to choose a video file",
                        style = MaterialTheme.typography.bodyMedium
                    )
                } else {
                    LaunchedEffect(screenModel.fileByteArray) {
                        thumbnail = generateThumbnail(
                            bytes = screenModel.fileByteArray!!,
                            mimeType = screenModel.platformFile?.mimeType()?.toString()
                                ?: "video/mp4"
                        )
                    }
                    if (thumbnail != null) {
                        AsyncImage(
                            model = thumbnail,
                            contentDescription = "video thumbnail",
                            modifier = Modifier.width(PixelDensity.getPixelDensity(200))
                        )
                    } else {
                        Image(
                            contentDescription = null,
                            painter = painterResource(Res.drawable.video),
                            modifier = Modifier.width(PixelDensity.getPixelDensity(200))
                        )
                    }
                }
                Text(
                    screenModel.platformFile?.name ?: "",
                    style = MaterialTheme.typography.bodySmall.copy(fontWeight = FontWeight.Bold)
                )
            }
            Text(
                "Supported formats: ${ExportVideoFormat.entries.joinToString(", ") { it.name.lowercase() }}",
                style = MaterialTheme.typography.bodyMedium
            )
        }

    }

    @Composable
    private fun TranscribeOutput(modifier: Modifier, screenModel: KimdeoSelectVideoScreenModel) {
        Column(
            modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            Text(
                "Transcription / Translation output",
                style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
            )
            AnimatedVisibility(
                screenModel.transcribeProcess.second.isNotEmpty(),
                content = {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Box(
                            Modifier.background(MaterialTheme.colorScheme.primaryContainer),
                            contentAlignment = Alignment.Center
                        ) {
                            Box(
                                modifier = Modifier.fillMaxWidth()
                                    .height(PixelDensity.EXTRA_LARGE * 3)
                                    .shimmerProgress(
                                        color = MaterialTheme.colorScheme.primary,
                                        shimmerColor = Color.Magenta,
                                        progress = screenModel.transcribeProcess.first / 100
                                    ),
                            )
                            Text(
                                text = screenModel.transcribeProcess.second,
                                style = MaterialTheme.typography.bodyMedium.copy(
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.background
                                )
                            )
                        }
                    }
                }
            )
        }
    }

