package api.auth.kimdeo.ui

import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.TextUnit
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp

object PixelDensity {
    val VERY_SMALL = 3.dp
    val SMALL = 6.dp


    val MEDIUM = 12.dp
    val LARGE = 18.dp


    val VERY_LARGE = 24.dp
    val EXTRA_LARGE = 36.dp

    fun <T: Number> getPixelDensity(density: T): Dp {
        return density.toDouble().dp
    }
    fun getPixelDensitySp(density: Int): TextUnit = density.sp
}