package api.auth.kimdeo.screens.setting

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.Icon
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.material3.TextButton
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalUriHandler
import androidx.compose.ui.text.font.FontWeight
import api.auth.kimdeo.model.ConnectionState
import api.auth.kimdeo.ui.DisplayPopup
import api.auth.kimdeo.ui.HorizontalTextIcon
import api.auth.kimdeo.ui.PixelDensity
import api.auth.kimdeo.ui.PulsingRing
import api.auth.kimdeo.ui.ReloadButton
import api.auth.kimdeo.ui.ShimmeringText
import api.auth.kimdeo.ui.horizontalScrollable
import api.auth.kimdeo.ui.outline
import api.auth.kimdeo.ui.underlineIf
import api.auth.kimdeo.ui.verticalScrollable
import cafe.adriel.voyager.core.model.rememberScreenModel
import cafe.adriel.voyager.core.screen.Screen
import compose.icons.TablerIcons
import compose.icons.tablericons.CreditCard
import compose.icons.tablericons.Forms
import compose.icons.tablericons.Shield
import kotlinx.coroutines.delay
import kotlin.time.Duration.Companion.milliseconds

object SettingsScreen : Screen {
    @Composable
    override fun Content() {
        val screenModel =
            rememberScreenModel { SettingScreenModel.apply { initializeScreenModel() } }
        DisplaySettingPopup(screenModel)
//        DisplayConfirmPopup(screenModel)
        DisplayConfirmPopupForSetting(screenModel)
        if (!screenModel.openWebUrl.isNullOrEmpty()) {
            val uriHandler = LocalUriHandler.current
            uriHandler.openUri(screenModel.openWebUrl!!)
            screenModel.openWebUrl = null
        }
        when (screenModel.connectionState) {
            is ConnectionState.OnFailure -> {
                Column(
                    Modifier.fillMaxSize(),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    ShimmeringText(text = (screenModel.connectionState as ConnectionState.OnFailure).data)
                    ReloadButton(
                        modifier = Modifier.padding(top = PixelDensity.LARGE),
                        colors = listOf(
                            MaterialTheme.colorScheme.primary,
                            MaterialTheme.colorScheme.background
                        ),
                        onReload = { screenModel.initializeScreenModel() },
                    )
                }
            }

            is ConnectionState.OnSucsess -> {
                Column(
                    modifier = Modifier.fillMaxSize().padding(PixelDensity.LARGE),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    SettingsHeaderDisplay(screenModel)
                    SettingsBodyDisplay(screenModel)
                }
            }

            else -> {
                Column(
                    Modifier.fillMaxSize(),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    val pulseBeforeShow = remember { mutableStateOf(false) }

                    LaunchedEffect(pulseBeforeShow) {
                        if (!pulseBeforeShow.value)
                            delay(5000.milliseconds)
                        pulseBeforeShow.value = true
                    }
                    PulsingRing()
                    if (pulseBeforeShow.value) {
                        ShimmeringText(
                            "Loading... seems to be taking a lot of time.",
                            modifier = Modifier.padding(top = PixelDensity.LARGE),
                        )
                        ReloadButton(
                            modifier = Modifier.padding(top = PixelDensity.LARGE),
                            colors = listOf(
                                MaterialTheme.colorScheme.primary,
                                MaterialTheme.colorScheme.background
                            ),
                            onReload = {
                                screenModel.initializeScreenModel()
                                pulseBeforeShow.value = false
                            },
                        )
                    }
                }
            }
        }
    }


    @Composable
    private fun SettingsBodyDisplay(screenModel: SettingScreenModel) {
        when (screenModel.settingScreenType) {
            SettingScreenType.BILLING -> BillingDisplay(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(PixelDensity.MEDIUM)
                    .verticalScrollable(),
                screenModel = screenModel,
            )

            SettingScreenType.ACCOUNT -> AccountDisplay(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(PixelDensity.MEDIUM).verticalScrollable(),
                screenModel = screenModel,
            )

            SettingScreenType.SECURITY -> SecurityDisplay(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(PixelDensity.MEDIUM).verticalScrollable(),
                screenModel = screenModel,
            )
        }
    }

    @Composable
    private fun SettingsHeaderDisplay(screenModel: SettingScreenModel) {
        Row(
            modifier = Modifier.fillMaxWidth().horizontalScrollable(),
            horizontalArrangement = Arrangement.Center,
            verticalAlignment = Alignment.CenterVertically
        ) {
            TextButton(
                modifier = Modifier.underlineIf(
                    condition = screenModel.settingScreenType == SettingScreenType.BILLING,
                    thickness = PixelDensity.VERY_SMALL
                ),
                onClick = { screenModel.settingScreenType = SettingScreenType.BILLING }
            ) {
                HorizontalTextIcon(
                    leadingContent = { Icon(TablerIcons.CreditCard, null) },
                    text = "Billing",
                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                )
            }
            TextButton(
                modifier = Modifier.underlineIf(
                    condition = screenModel.settingScreenType == SettingScreenType.ACCOUNT,
                    thickness = PixelDensity.VERY_SMALL
                ),
                onClick = { screenModel.settingScreenType = SettingScreenType.ACCOUNT }
            ) {
                HorizontalTextIcon(
                    leadingContent = { Icon(TablerIcons.Forms, null) },
                    text = "Account",
                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                )
            }
            TextButton(
                modifier = Modifier.underlineIf(
                    condition = screenModel.settingScreenType == SettingScreenType.SECURITY,
                    thickness = PixelDensity.VERY_SMALL
                ),
                onClick = { screenModel.settingScreenType = SettingScreenType.SECURITY }
            ) {
                HorizontalTextIcon(
                    leadingContent = { Icon(TablerIcons.Shield, null) },
                    text = "Security",
                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                )
            }
        }
    }

    @Composable
    fun DisplayConfirmPopupForSetting(screenModel: SettingScreenModel) {
        DisplayPopup(
            show = screenModel.confirmationPopup.show,
            onDismiss = {
                if (screenModel.confirmationPopup.isDismissible) {
                    screenModel.dismissConfirmPopup()
                }
            },

            content = {
                Column(
                    modifier = Modifier
                        .padding(PixelDensity.LARGE)
                        .outline()
                        .background(
                            color = MaterialTheme.colorScheme.background.copy(alpha = 0.5f),
                            shape = MaterialTheme.shapes.small
                        ).padding(PixelDensity.MEDIUM),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                ) {
                    Text(
                        text = screenModel.confirmationPopup.title,
                        style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold),
                    )
                    Text(
                        text = screenModel.confirmationPopup.description,
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                    )
                    screenModel.confirmationPopup.content(this)
                }
            },
        )
    }

    @Composable
    private fun DisplaySettingPopup(screenModel: SettingScreenModel) {
        DisplayPopup(
            show = screenModel.settingPopup.show,
            onDismiss = {
                if (screenModel.settingPopup.isDismissible) {
                    screenModel.dismissPopups()
                }
            },
            content = {
                Column(
                    modifier = Modifier
                        .padding(PixelDensity.LARGE)
                        .outline()
                        .background(
                            color = MaterialTheme.colorScheme.background.copy(alpha = 0.5f),
                            shape = MaterialTheme.shapes.small
                        ).padding(PixelDensity.MEDIUM),
                    verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                ) {
                    HorizontalTextIcon(
                        leadingContent = { screenModel.settingPopup.content() },
                        text = screenModel.settingPopup.title,
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                        horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
                    )
                    Text(
                        text = screenModel.settingPopup.description,
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                    )
                }
            }
        )

    }
}
