fun HttpClientConfig<*>.commonNormalConfig() {
    expectSuccess = true
    install(Logging)
    install(ContentNegotiation) {
        json()
    }
}

fun HttpClientConfig<*>.commonConfig() {
    expectSuccess = true
    install(Auth) {
        bearer {
            loadTokens {
                try {
                    val token = PreferenceManager.getInvokeLogin().token

                    BearerTokens(
                        accessToken = token,
                        refreshToken = ""
                    )

                } catch (e: Exception) {
                    PreferenceManager.saveInvokeLogin(
                        InvokeLogIn(
                            token = "",
                            shouldLogin = true,
                            alreadyLogin = true
                        )
                    )
                    null
                }
            }
        }
    }
    install(Logging)
    install(WebSockets) {
        pingInterval = 15.seconds
    }
    install(ContentNegotiation) {
        json()
    }
}

fun HttpClientConfig<*>.commonAuthConfig() {
    expectSuccess = true
    install(Auth) {
        bearer {
            loadTokens {
                BearerTokens(
                    accessToken = BuildConfig.API_AUTH_KEY,   // your JWT
//                    accessToken = PreferenceManager.getInvokeLogin().token,   // your JWT
                    refreshToken = ""  // optional
                )
            }
        }
    }
    install(Logging)
    install(ContentNegotiation) {
        json()
    }
}

