@Composable
fun BillingDisplay(
    modifier: Modifier,
    screenModel: SettingScreenModel,
) {
    Column(
        modifier = modifier,
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
    ) {
        Text(
            text = "Choose Your Plan",
            style = MaterialTheme.typography.headlineSmall
        )
        Text(
            text = "Select the perfect plan for your transcription needs. All plans include our industry-leading AI with 95%+ accuracy.",
            style = MaterialTheme.typography.bodyMedium
        )
        PlanDisplay(
            modifier = Modifier.fillMaxWidth(),
            screenModel = screenModel,
        )
        AskedQuestionsDisplay(modifier = Modifier.fillMaxWidth())
    }
}


@Composable
fun AskedQuestionsDisplay(modifier: Modifier) {
