        modifier = modifier,
        verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
    ) {
        Text("Frequently Asked Questions", style = MaterialTheme.typography.headlineSmall)
        Surface(
            shape = MaterialTheme.shapes.medium,
            tonalElevation = PixelDensity.VERY_SMALL
        ) {
            DisplayExpandableVertical(
                modifier = Modifier.fillMaxWidth().padding(PixelDensity.MEDIUM),
                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                text = "Can I switch plans at any time?",
                imageVectorOpen = TablerIcons.ChevronUp,
                imageVectorClose = TablerIcons.ChevronDown,
                contents = listOf(
                    "Yes, you can upgrade or downgrade your plan at any time. When upgrading, your previous plan will be canceled, the changes will take effect at the start of your next billing cycle."
                )
            )
        }
        Surface(
            shape = MaterialTheme.shapes.medium,
            tonalElevation = PixelDensity.VERY_SMALL
        ) {
            DisplayExpandableVertical(
                modifier = Modifier.fillMaxWidth().padding(PixelDensity.MEDIUM),
                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                text = "Is there a limit on file size?",
                imageVectorOpen = TablerIcons.ChevronUp,
                imageVectorClose = TablerIcons.ChevronDown,
                contents = listOf(
                    "Yes thee is a limit to file size, you can only upload files up to ${Constants.UPLOAD_FILE_SIZE}mb"
                )
            )
        }
        Surface(
            shape = MaterialTheme.shapes.medium,
            tonalElevation = PixelDensity.VERY_SMALL
        ) {
            DisplayExpandableVertical(
                modifier = Modifier.fillMaxWidth().padding(PixelDensity.MEDIUM),
                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                text = "How accurate is the transcription?",
                imageVectorOpen = TablerIcons.ChevronUp,
                imageVectorClose = TablerIcons.ChevronDown,
                contents = listOf(
                    "Our AI achieves 95%+ accuracy on average. Accuracy can vary based on audio quality, background noise, accents, and technical terminology."
                )
            )
        }
        Surface(
            shape = MaterialTheme.shapes.medium,
            tonalElevation = PixelDensity.VERY_SMALL
        ) {
            DisplayExpandableVertical(
                modifier = Modifier.fillMaxWidth().padding(PixelDensity.MEDIUM),
                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                text = "What languages are supported?",
                imageVectorOpen = TablerIcons.ChevronUp,
                imageVectorClose = TablerIcons.ChevronDown,
                contents = listOf(
                    "We support over 50 languages including English, Spanish, French, German, Chinese, Japanese, Arabic, and many more."
                )
            )
        }
        Surface(
            shape = MaterialTheme.shapes.medium,
            tonalElevation = PixelDensity.VERY_SMALL
        ) {
            DisplayExpandableVertical(
                modifier = Modifier.fillMaxWidth().padding(PixelDensity.MEDIUM),
                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                text = "Can I cancel my subscription anytime?",
                imageVectorOpen = TablerIcons.ChevronUp,
                imageVectorClose = TablerIcons.ChevronDown,
                contents = listOf(
                    "Yes, you can cancel your subscription at any time. If you cancel, you'll continue to have access to your plan features until the end of your current billing period."
                )
            )
        }
    }
}


@Composable
fun PlanDisplay(
    modifier: Modifier,
    screenModel: SettingScreenModel,
) {
    val deviceInfo = rememberDeviceInfo()
    FlowRow(
        modifier = modifier,
        maxItemsInEachRow = if (deviceInfo.orientation == Orientation.PORTRAIT) 1 else 3,
        horizontalArrangement = Arrangement.Center,
    ) {
        for (subPlan in screenModel.subscriptionPlans) {
            BillingPlanDisplay(
                modifier = Modifier
                    .outline(
                        color = if (screenModel.planInterval == subPlan.interval) MaterialTheme.colorScheme.secondary else MaterialTheme.colorScheme.background,
                        width = PixelDensity.VERY_SMALL
                    )
                    .padding(PixelDensity.LARGE),
                planModel = subPlan,
                country = screenModel.userModel.country,
                onClick = {
                    screenModel.planInterval = subPlan.interval
                    screenModel.showConfirmPopup(
                        ConfirmPopupModel(
                            show = true,
                            title = "Confirm ${
                                screenModel.planInterval.name.replace("_", " ").lowercase()
                            } Plan Payment",
                            description = "Please review the details below before proceeding:",
                            content = {
                                Column(
                                    modifier = Modifier.padding(PixelDensity.MEDIUM),
                                    horizontalAlignment = Alignment.CenterHorizontally
                                ) {
                                    HorizontalTextIcon(
                                        leadingContent = {
                                            Icon(
                                                TablerIcons.Lock,
                                                null,
                                                tint = Color.Yellow
                                            )
                                        },
                                        text = "• Payments are securely processed via Paystack, a trusted payment gateway in Nigeria and across Africa.",
                                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                                    )
                                    HorizontalTextIcon(
                                        leadingContent = {
                                            Icon(
                                                TablerIcons.Key,
                                                null,
                                                tint = Color.Cyan
                                            )
                                        },
                                        text = "• Your transaction is encrypted and handled according to industry security standards.",
                                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                                    )
                                    HorizontalTextIcon(
                                        leadingContent = {
                                            Icon(
                                                TablerIcons.Wallet,
                                                null,
                                                tint = Color.Yellow
                                            )
                                        },
                                        text = "• You will be redirected to Paystack’s secure payment page to complete your subscription.",
                                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                                    )
                                    HorizontalTextIcon(
                                        leadingContent = {
                                            Icon(
                                                TablerIcons.Walk,
                                                null,
                                            )
                                        },
                                        text = "• By clicking 'Proceed', you agree to continue with this transaction.",
                                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                                    )
                                    ElevatedButton(
                                        onClick = {
                                            screenModel.paymentPlan(
                                                subPlan.interval,
                                                {
                                                    if (it != null) {
                                                        screenModel.openWebUrl = it
                                                    } else {
                                                        screenModel.showPopup(
                                                            PopupModel(
                                                                show = true,
                                                                title = "Payment Error",
                                                                description = "There was an error creating a payment gateway",
                                                                content = {
                                                                    Icon(
                                                                        TablerIcons.AlertTriangle,
                                                                        null,
                                                                        tint = Color.Red
                                                                    )
                                                                }
                                                            ))
                                                    }
                                                }
                                            )
                                        }
                                    ) {
                                        HorizontalTextIcon(
                                            leadingContent = {
                                                Icon(
                                                    TablerIcons.CurrencyDollar,
                                                    null,
                                                    tint = Color.Cyan
                                                )
                                            },
                                            text = "Proceed",
                                            style = MaterialTheme.typography.bodyMedium.copy(
                                                fontWeight = FontWeight.Bold
                                            )
                                        )
                                    }
                                }
                            },
                            isDismissible = true
                        )
                    )
//                    screenModel.confirmPopupTypeChange(ConfirmationPopupType.PAY_PLAN)
                }
            )
        }
    }
}


@Composable
private fun BillingPlanDisplay(
    modifier: Modifier,
    planModel: PlanModel,
    onClick: () -> Unit,
    country: KimCountry
) {
    Surface(
        modifier = modifier,
        tonalElevation = PixelDensity.VERY_SMALL,
        shape = MaterialTheme.shapes.medium
    ) {
        Column(
            modifier = Modifier.padding(PixelDensity.VERY_LARGE),
            verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
        ) {
            val apd =
                remember(planModel) { if (country.currencyIcon != null) country.amountToNaira else 1.0 }
            Text(planModel.name, style = MaterialTheme.typography.headlineMedium)
            Text(
                planModel.description,
                style = MaterialTheme.typography.bodyMedium.copy(color = MaterialTheme.colorScheme.tertiary)
            )
            Row {
                Icon(
                    country.currencyIcon ?: TablerIcons.CurrencyDollar,
                    null,
                    tint = Color.Cyan
                )
                StyledText(
                    contents = listOf(
                        ComTextModel(
                            text = (planModel.price * apd).toReadableCommaFormat(),
                            style = MaterialTheme.typography.headlineSmall.toSpanStyle(),
                        ),
                        ComTextModel(
                            text = "/${planModel.interval.name.lowercase()}",
                            style = MaterialTheme.typography.bodyMedium.toSpanStyle(),
                        )
                    )
                )
            }
            StyledText(
                contents = listOf(
                    ComTextModel(
                        text = "Credits: ",
                        style = MaterialTheme.typography.bodyMedium.copy(
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary
                        ).toSpanStyle()
                    ),
                    ComTextModel(
                        text = " ${planModel.credits.toReadableCommaFormat()}",
                        style = MaterialTheme.typography.bodyMedium.copy(
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.secondary
                        ).toSpanStyle()
                    ),
                )
            )
            for (feature in planModel.features) {
                HorizontalTextIcon(
                    leadingContent = {
                        Icon(
                            TablerIcons.InfoCircle,
                            null,
                            tint = MaterialTheme.colorScheme.secondary
                        )
                    },
                    text = feature,
                    style = MaterialTheme.typography.bodyMedium.copy(
                        fontWeight = FontWeight.Bold,
                    )
                )
            }

            OutlinedButton(onClick = onClick) {
                Text(
                    text = "Get Started",
                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                )
            }
        }
    }
}