object PlayGSelectVideo : Screen {
    @OptIn(ExperimentalMaterial3Api::class)
    @Composable
    override fun Content() {
        val navigator = LocalNavigator.currentOrThrow
        // Reuses the same instance
        val screenModel = navigator.rememberNavigatorScreenModel { PlayGroundViewModel() }
        val deviceInfo = rememberDeviceInfo()
        LaunchedEffect(screenModel.audioByteArray) {
            if (screenModel.audioByteArray != null) {
                screenModel.audioPlayerDisposable = loadHiddenAudioMetadata(
                    bytes = screenModel.audioByteArray!!,
                    mimeType = "audio/wav",
                    onReady = { interaction ->
                        if (screenModel.audioController == null) screenModel.attachAudioController(
                            interaction
                        )
                    }
                )
            }
        }
        Scaffold(
            modifier = Modifier.fillMaxSize(),
            topBar = {
                TopAppBar(
                    colors = TopAppBarDefaults.topAppBarColors(
                        containerColor = MaterialTheme.colorScheme.tertiary,
                        titleContentColor = MaterialTheme.colorScheme.onTertiary,
                        navigationIconContentColor = MaterialTheme.colorScheme.onTertiary,
                    ),
                    navigationIcon = {
                        IconButton(onClick = {
                            screenModel.onBackPressed()
                            navigator.pop()
                        }, content = {
                            Icon(
                                TablerIcons.ArrowLeft, null
                            )
                        })
                    },
                    actions = {
                        ResetReloadButton(
                            onClicked = { screenModel.resetScreenModel() },
                            imageVector = TablerIcons.Refresh,
                            isResetting = screenModel.isResetting,
                            color = MaterialTheme.colorScheme.onPrimary
                        )
                    },
                    title = {
                        Text(
                            "KimDeo AI Playground",
                            style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
                        )
                    }
                )
            },
            bottomBar = {
                if (deviceInfo.orientation == Orientation.PORTRAIT) {
                    Box(
                        Modifier.padding(PixelDensity.SMALL)
                            .background(MaterialTheme.colorScheme.primaryContainer),
                        contentAlignment = Alignment.Center
                    ) {
                        Box(
                            modifier = Modifier.fillMaxWidth()
                                .shimmerProgress(
                                    speed = 2000,
                                    colors = listOf(
                                        MaterialTheme.colorScheme.primary,
                                        MaterialTheme.colorScheme.secondary
                                    ),
                                    progress = screenModel.transcribeProcess.first / 100,
                                    backgroundColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.5f)
                                ).padding(PixelDensity.LARGE),
                        )
                        Text(
                            text = screenModel.transcribeProcess.second,
                            style = MaterialTheme.typography.bodyMedium.copy(
                                textAlign = TextAlign.Center,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.background
                            )
                        )
                    }
                }
            },
            content = { pv ->
                DisplayPopup(
                    show = screenModel.playGroundPopup.show,
                    onDismiss = {
                        if (screenModel.playGroundPopup.isDismissible) {
                            screenModel.playGroundPopup = PopupModel()
                        }
                    },
                    content = {
                        Column(
                            Modifier.outline().padding(PixelDensity.MEDIUM).background(
                                shape = MaterialTheme.shapes.medium,
                                color = MaterialTheme.colorScheme.background
                            ),
                            verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
                        ) {
                            HorizontalTextIcon(
                                leadingContent = { screenModel.playGroundPopup.content() },
                                text = screenModel.playGroundPopup.title,
                                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold)
                            )
                            Text(
                                text = screenModel.playGroundPopup.description,
                                style = MaterialTheme.typography.bodyMedium
                            )
                        }
                    }
                )
                Column(
                    modifier = Modifier.padding(pv)
                        .fillMaxSize()
                        .padding(PixelDensity.MEDIUM)
                        .verticalScrollable(),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    when (deviceInfo.orientation) {
                        Orientation.PORTRAIT -> {
                            ElevatedCard(
                                modifier = Modifier.fillMaxWidth().padding(PixelDensity.SMALL),
                            ) {
                                SelectFileCard(
                                    modifier = Modifier.fillMaxWidth().padding(PixelDensity.MEDIUM),
                                    screenModel = screenModel
                                )
                            }
                            Spacer(Modifier.height(PixelDensity.EXTRA_LARGE))
                            ElevatedCard(
                                modifier = Modifier.fillMaxWidth().padding(PixelDensity.SMALL),
                            ) {
                                TranscribeFileCard(
                                    modifier = Modifier.fillMaxWidth()
                                        .padding(PixelDensity.MEDIUM),
                                    navigator = navigator,
                                    screenModel = screenModel,
                                )
                            }
                        }

                        else -> {
                            Row(
                                horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                ElevatedCard(
                                    modifier = Modifier.weight(1f).padding(PixelDensity.SMALL),
                                ) {
                                    SelectFileCard(
                                        modifier = Modifier.padding(PixelDensity.MEDIUM)
                                            .fillMaxWidth(),
                                        screenModel = screenModel
                                    )
                                }
                                ElevatedCard(
                                    modifier = Modifier.weight(1f).padding(PixelDensity.SMALL),
                                ) {
                                    TranscribeFileCard(
                                        modifier = Modifier.padding(PixelDensity.MEDIUM)
                                            .fillMaxWidth(),
                                        navigator = navigator,
                                        screenModel = screenModel,
                                    )
                                }
                            }
                            Spacer(Modifier.height(PixelDensity.EXTRA_LARGE))
                            TranscribeOutput(
                                modifier = Modifier.width(PixelDensity.getPixelDensity(deviceInfo.width / 1.5))
                                    .padding(PixelDensity.SMALL),
                                screenModel = screenModel
                            )
                        }
                    }
                }
            }
        )
    }


    @Composable
    private fun SelectFileCard(modifier: Modifier, screenModel: PlayGroundViewModel) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            Column(
                Modifier
                    .outline()
                    .clickable(
                        enabled = screenModel.enableButton,
                        onClick = { screenModel.getMediaFile() })
                    .padding(horizontal = PixelDensity.MEDIUM, vertical = PixelDensity.LARGE),
                verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                var thumbnail by remember {
                    mutableStateOf<String?>(null)
                }
                if (screenModel.fileByteArray == null) {
                    Icon(
                        contentDescription = null,
                        imageVector = TablerIcons.Folder,
                        modifier = Modifier.size(PixelDensity.getPixelDensity(100))
                    )
                    Text(
                        text = "Click to choose a video file",
                        style = MaterialTheme.typography.bodyMedium
                    )
                } else {
                    LaunchedEffect(screenModel.fileByteArray) {
                        thumbnail = generateThumbnail(
                            bytes = screenModel.fileByteArray!!,
                            mimeType = screenModel.platformFile?.mimeType()?.toString()
                                ?: "video/mp4"
                        )
                    }
                    if (thumbnail != null) {
                        AsyncImage(
                            model = thumbnail,
                            contentDescription = "video thumbnail",
                            modifier = Modifier.width(PixelDensity.getPixelDensity(200))
                        )
                    } else {
                        Image(
                            contentDescription = null,
                            painter = painterResource(Res.drawable.video),
                            modifier = Modifier.width(PixelDensity.getPixelDensity(200))
                        )
                    }
                }
                Text(
                    screenModel.platformFile?.name ?: "",
                    style = MaterialTheme.typography.bodyMedium
                )
            }
            Text(
                "Supported formats: ${ExportVideoFormat.entries.joinToString(", ") { it.name.lowercase() }}",
                style = MaterialTheme.typography.bodyMedium
            )
        }
    }

    @Composable
    private fun TranscribeFileCard(
        modifier: Modifier,
        navigator: Navigator,
        screenModel: PlayGroundViewModel,
    ) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            var selectedKimLanguage by remember { mutableStateOf("") }
            var expandLanguage by remember { mutableStateOf(false) }
            Text(
                text = "Configure Video",
                style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
            )
            OutlinedButton(
                modifier = Modifier.fillMaxWidth(),
                enabled = (screenModel.fileByteArray != null) && screenModel.enableButton,
                onClick = { expandLanguage = !expandLanguage },
                content = {
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        StyledText(
                            contents = listOf(
                                ComTextModel(
                                    text = "Select Language ",
                                    style = MaterialTheme.typography.bodyMedium.toSpanStyle()
                                ),
                                ComTextModel(
                                    text = "(${screenModel.kimLanguage})",
                                    style = MaterialTheme.typography.bodyMedium.copy(color = MaterialTheme.colorScheme.secondary)
                                        .toSpanStyle()
                                )
                            )
                        )
                        Icon(
                            if (expandLanguage) TablerIcons.ChevronUp else TablerIcons.ChevronDown,
                            contentDescription = "expand languages"
                        )
                    }
                })
            AnimatedVisibility(expandLanguage, content = {
                SelectLanguages(
                    selectedKimLanguage,
                    kimLanguage = screenModel.kimLanguage,
                    kimLanguages = screenModel.kimLanguages,
                    onLangNalChanged = {
                        selectedKimLanguage = it
                        screenModel.checkKimLanguages(it)
                    },
                    onClear = {
                        selectedKimLanguage = ""
                        screenModel.checkKimLanguages("")
                    },
                    onSelect = {
                        screenModel.kimLanguage = it
                        expandLanguage = !expandLanguage
                    }
                )
            })
            OutlinedButton(
                modifier = Modifier.fillMaxWidth(),
                enabled = (screenModel.fileByteArray != null) && screenModel.enableButton,
                onClick = { screenModel.transcribeVideo() },
                content = {
                    HorizontalTextIcon(
                        leadingContent = { Icon(TablerIcons.Stars, null) },
                        text = "Transcribe Video",
                        style = MaterialTheme.typography.bodyMedium
                    )
                })
            OutlinedButton(
                modifier = Modifier.fillMaxWidth(),
                enabled = (screenModel.fileByteArray != null) && screenModel.enableButton,
                onClick = {
                    navigator.push(PlayGVideoPlayer)
                    screenModel.onWatchClicked()
                },
                content = {
                    HorizontalTextIcon(
                        leadingContent = { Icon(TablerIcons.Video, null) },
                        text = "Watch Video",
                        style = MaterialTheme.typography.bodyMedium
                    )
                })
        }
    }

    @Composable
    private fun TranscribeOutput(modifier: Modifier, screenModel: PlayGroundViewModel) {
        Surface(
            shape = MaterialTheme.shapes.small,
            tonalElevation = PixelDensity.VERY_SMALL,
            shadowElevation = PixelDensity.VERY_SMALL
        ) {
            Column(
                modifier,
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
            ) {
                Text(
                    "Transcription / Translation output",
                    style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
                )
                AnimatedVisibility(
                    screenModel.transcribeProcess.second.isNotEmpty(),
                    content = {
                        Column(horizontalAlignment = Alignment.CenterHorizontally) {
                            Box(
                                Modifier.background(MaterialTheme.colorScheme.primaryContainer),
                                contentAlignment = Alignment.Center
                            ) {
                                Box(
                                    modifier = Modifier.fillMaxWidth()
                                        .shimmerProgress(
                                            speed = 2000,
                                            colors = listOf(
                                                MaterialTheme.colorScheme.primary,
                                                MaterialTheme.colorScheme.secondary
                                            ),
                                            progress = screenModel.transcribeProcess.first / 100,
                                            backgroundColor = MaterialTheme.colorScheme.primary.copy(
                                                alpha = 0.5f
                                            )
                                        ).padding(PixelDensity.LARGE),
                                )
                                Text(
                                    text = screenModel.transcribeProcess.second,
                                    style = MaterialTheme.typography.bodyMedium.copy(
                                        textAlign = TextAlign.Center,
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.background
                                    )
                                )
                            }
                        }
                    }
                )
            }
        }
    }
}