@Composable
fun AccountDisplay(modifier: Modifier, screenModel: SettingScreenModel) {
    val deviceInfo = rememberDeviceInfo()
    Column(
        modifier = modifier,
        verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
    ) {
        when (deviceInfo.orientation) {
            Orientation.PORTRAIT -> ProfileSettingDisplayPortrait(
                modifier = Modifier.fillMaxWidth(),
                screenModel = screenModel,
                onUpdate = {}
            )

            else -> ProfileSettingDisplay(
                modifier = Modifier.fillMaxWidth(),
                screenModel = screenModel,
            )
        }

    }
}

// COLUMN SCOPE
@Composable
private fun ProfileSettingDisplay(
    modifier: Modifier,
    screenModel: SettingScreenModel,
) {
    Column(modifier = modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        UpdateProfileImage(
            modifier = Modifier.padding(PixelDensity.LARGE),
            screenModel = screenModel
        )
        Surface(
            modifier = Modifier.padding(PixelDensity.LARGE),
            tonalElevation = PixelDensity.VERY_SMALL
        ) {
            Column(
                modifier = Modifier.padding(PixelDensity.MEDIUM).fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Text(text = "Profile Settings", style = MaterialTheme.typography.headlineSmall)
                HorizontalDivider()
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    OutlinedTextField(
                        modifier = Modifier.weight(1f),
                        isError = screenModel.firstName.isEmpty(),
                        value = screenModel.firstName,
                        onValueChange = { screenModel.firstName = it },
                        label = {
                            Text(
                                "First Name",
                                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                            )
                        },
                        placeholder = { Text(text = "Please enter your first name") },
                        keyboardOptions = KeyboardOptions(capitalization = KeyboardCapitalization.Words)
                    )
                    OutlinedTextField(
                        modifier = Modifier.weight(1f),
                        isError = screenModel.lastName.isEmpty(),
                        value = screenModel.lastName,
                        onValueChange = { screenModel.lastName = it },
                        label = {
                            Text(
                                "Last Name",
                                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                            )
                        },
                        placeholder = { Text(text = "Please enter your last name") },
                        keyboardOptions = KeyboardOptions(capitalization = KeyboardCapitalization.Words)
                    )
                }
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    OutlinedTextField(
                        modifier = Modifier.weight(1f),
                        isError = screenModel.email.isEmpty(),
                        value = screenModel.email,
                        onValueChange = { screenModel.email = it },
                        label = {
                            Text(
                                "Email Address",
                                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                            )
                        },
                        placeholder = { Text(text = "Please enter your email") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Email)
                    )
                    OutlinedTextField(
                        modifier = Modifier.weight(1f),
                        isError = screenModel.phoneNumber.isEmpty(),
                        value = screenModel.phoneNumber,
                        onValueChange = { screenModel.phoneNumber = it },
                        label = {
                            Text(
                                "Phone Number",
                                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                            )
                        },
                        placeholder = { Text(text = "(+XXX) XXX XXX XXX XX") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone)
                    )
                }
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    OutlinedTextField(
                        modifier = Modifier.weight(1f),
                        isError = screenModel.dateOfBirth.isEmpty(),
                        value = screenModel.dateOfBirth,
                        onValueChange = { screenModel.dateOfBirth = it },
                        label = {
                            Text(
                                "Date of Birth",
                                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                            )
                        },
                        placeholder = { Text(text = "day/month/year") },
                        keyboardOptions = KeyboardOptions(capitalization = KeyboardCapitalization.Words)
                    )
                    OutlinedTextField(
                        modifier = Modifier.weight(1f),
                        isError = screenModel.roleTitle.isEmpty(),
                        value = screenModel.roleTitle,
                        onValueChange = { screenModel.roleTitle = it },
                        label = {
                            Text(
                                "Role",
                                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                            )
                        },
                        placeholder = { Text(text = "please enter your company name") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Text)
                    )
                }
                Button(
                    onClick = {
                        screenModel.showConfirmPopup(
                            ConfirmPopupModel(
                                show = true,
                                title = "Update User",
                                description = "You are about to update your user details, Please click 'proceed' to continue",
                                content = {
                                    ElevatedButton(onClick = {
                                        screenModel.updateUserProfile()
                                    }) {
                                        HorizontalTextIcon(
                                            leadingContent = { Icon(TablerIcons.UserPlus, null) },
                                            text = "Proceed",
                                            style = MaterialTheme.typography.bodyMedium.copy(
                                                fontWeight = FontWeight.Bold
                                            )
                                        )
                                    }
                                },
                            )
                        )

//                        screenModel.settingPopupTypeChange(SettingPopupType.UpdateProfile)
                    }) {
                    Text(
                        text = "Update Profile",
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                    )
                }
            }
        }

    }
}

@Composable
fun UpdateProfileImage(modifier: Modifier, screenModel: SettingScreenModel) {
    Surface(
        modifier = modifier,
        tonalElevation = PixelDensity.VERY_SMALL
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Box(
                modifier = Modifier
                    .widthIn(
                        min = PixelDensity.getPixelDensity(120),
                        max = PixelDensity.getPixelDensity(240)
                    )
                    .heightIn(min = PixelDensity.getPixelDensity(120),)
                    .padding(PixelDensity.LARGE)
                    .clickable(onClick = { screenModel.selectImage() }),
                contentAlignment = Alignment.Center
            ) {
                SubcomposeAsyncImage(
                    model = screenModel.userImage,//use profile image
                    contentDescription = "profile image",
                    contentScale = ContentScale.Crop,
                    loading = { Icon(TablerIcons.Photo, null) },
                    error = { Icon(TablerIcons.Photo, null) }
                )
            }
            Button(onClick = {
                screenModel.updateUserProfileImage()
            }) {
                HorizontalTextIcon(
                    leadingContent = { Icon(TablerIcons.FileExport, null) },
                    text = "Change Profile Image",
                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                )
            }
        }
    }
}


