object ProfileScreen : Screen {
    @Composable
    override fun Content() {
        val screenModel =
            rememberScreenModel { ProfileScreenModel().apply { initialiseScreenModel() } }
        val deviceInfo = rememberDeviceInfo()
        val navigator = LocalNavigator.currentOrThrow
        Scaffold(
            modifier = Modifier.fillMaxSize(),
            floatingActionButton = {
                if (deviceInfo.orientation == Orientation.PORTRAIT) {
                    ExtendedFloatingActionButton(
                        text = {
                            Text(
                                text = if (screenModel.toggleProfile) "Profile" else "transcription",
                                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.ExtraBold)
                            )
                        },
                        icon = {
                            Icon(
                                if (screenModel.toggleProfile) TablerIcons.UserX else TablerIcons.ListSearch,
                                null
                            )
                        },
                        onClick = { screenModel.toggleProfile = !screenModel.toggleProfile }
                    )
                }
            }
        ) { pv ->
            when (screenModel.profilePopup) {
                ProfilePopupType.SHOW_SUBSCRIBE -> {
                    DisplayPopup(
                        show = screenModel.profilePopup == ProfilePopupType.SHOW_SUBSCRIBE,
                        onDismiss = { screenModel.showProfilePopup(ProfilePopupType.NONE) },
                        content = {
                            Column(
                                modifier = Modifier.background(
                                    color = MaterialTheme.colorScheme.secondary,
                                    shape = MaterialTheme.shapes.medium
                                ).padding(PixelDensity.SMALL),
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
                            ) {
                                Text(
                                    text = "Subscription Plan",
                                    style = MaterialTheme.typography.headlineSmall.copy(color = MaterialTheme.colorScheme.onSecondary)
                                )
                                Column(
                                    modifier = Modifier.background(
                                        color = MaterialTheme.colorScheme.surfaceVariant,
                                        shape = MaterialTheme.shapes.medium
                                    ).padding(PixelDensity.MEDIUM),
                                    verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
                                ) {
                                    Text(
                                        text = "Pro Plan",
                                        style = MaterialTheme.typography.headlineSmall
                                    )
                                    Text(
                                        text = "Unlimited transcriptions with advanced AI models",
                                        style = MaterialTheme.typography.bodyMedium
                                    )
                                    HorizontalTextIcon(
                                        leadingContent = { Icon(TablerIcons.Check, null) },
                                        text = " Unlimited audio/video files",
                                        style = MaterialTheme.typography.bodyMedium
                                    )
                                    HorizontalTextIcon(
                                        leadingContent = { Icon(TablerIcons.Check, null) },
                                        text = " Up to 10 hour file length",
                                        style = MaterialTheme.typography.bodyMedium
                                    )
                                    HorizontalTextIcon(
                                        leadingContent = { Icon(TablerIcons.Check, null) },
                                        text = " Multiple export formats",
                                        style = MaterialTheme.typography.bodyMedium
                                    )
                                    HorizontalTextIcon(
                                        leadingContent = { Icon(TablerIcons.Check, null) },
                                        text = " Priority processing",
                                        style = MaterialTheme.typography.bodyMedium
                                    )
                                    HorizontalTextIcon(
                                        leadingContent = { Icon(TablerIcons.Check, null) },
                                        text = " Speaker identification",
                                        style = MaterialTheme.typography.bodyMedium
                                    )
                                    StyledText(
                                        contents = listOf(
                                            ComTextModel(
                                                text = "Renews on: ",
                                                style = MaterialTheme.typography.bodyMedium.copy(
                                                    fontWeight = FontWeight.Bold,
                                                    color = MaterialTheme.colorScheme.onPrimary
                                                ).toSpanStyle()
                                            ),
                                            ComTextModel(
                                                text = " November 15, 2023",
                                                style = MaterialTheme.typography.bodyMedium.copy(
                                                    fontWeight = FontWeight.Bold
                                                )
                                                    .toSpanStyle()
                                            ),
                                        )
                                    )
                                    HorizontalTextIcon(
                                        modifier = Modifier.background(
                                            color = MaterialTheme.colorScheme.primary,
                                            shape = MaterialTheme.shapes.medium
                                        ).padding(
                                            horizontal = PixelDensity.LARGE,
                                            vertical = PixelDensity.SMALL
                                        ).clickable(onClick = {}),
                                        leadingContent = {
                                            Icon(
                                                TablerIcons.Rocket,
                                                null,
                                                tint = MaterialTheme.colorScheme.onPrimary
                                            )
                                        },
                                        text = "Upgrade Plan",
                                        style = MaterialTheme.typography.bodyMedium.copy(
                                            fontWeight = FontWeight.Bold,
                                            color = MaterialTheme.colorScheme.onPrimary
                                        )
                                    )
                                }
                            }
                        }
                    )
                }

                else -> {
                    DisplayPopup(
                        show = screenModel.popupMessage.show,
                        onDismiss = { screenModel.popupMessage = PopupModel() },
                        content = {
                            Column(
                                modifier = Modifier.outline(
                                    color = MaterialTheme.colorScheme.onBackground,
                                    bgColor = MaterialTheme.colorScheme.background,
                                    padding = PixelDensity.SMALL,
                                    shape = MaterialTheme.shapes.small
                                ),
                                verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
                            ) {
                                HorizontalTextIcon(
                                    leadingContent = screenModel.popupMessage.content,
                                    horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                                    text = screenModel.popupMessage.title,
                                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                                )
                                Text(
                                    text = screenModel.popupMessage.description,
                                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                                )
                            }
                        },
                    )
                }

            }

            when (screenModel.connectionState) {
                is ConnectionState.OnFailure -> {
                    Column(
                        Modifier.fillMaxSize().padding(pv),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center
                    ) {
                        ShimmeringText(text = (screenModel.connectionState as ConnectionState.OnFailure).data)
                        ReloadButton(
                            modifier = Modifier.padding(top = PixelDensity.LARGE),
                            colors = listOf(
                                MaterialTheme.colorScheme.primary,
                                MaterialTheme.colorScheme.background
                            ),
                            onReload = { screenModel.initialiseScreenModel() },
                        )
                    }
                }

                is ConnectionState.OnSucsess -> {
                    when (deviceInfo.orientation) {
                        Orientation.PORTRAIT -> {
                            if (screenModel.toggleProfile) {
                                Column(
                                    modifier = Modifier.fillMaxSize().padding(pv),
                                    verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                                ) {
                                    Row(
                                        Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceAround
                                    ) {
                                        HorizontalTextIcon(
                                            modifier = Modifier.padding(
                                                horizontal = PixelDensity.MEDIUM,
                                                vertical = PixelDensity.SMALL
                                            ).clickable(onClick = {
                                                if (screenModel.pagerLimit > 5)
                                                    screenModel.pagerLimit--
                                            }).outline(),
                                            leadingContent = { Icon(TablerIcons.ArrowLeft, null) },
                                            text = "back",
                                            style = MaterialTheme.typography.bodySmall.copy(
                                                color = MaterialTheme.colorScheme.primary,
                                                fontWeight = FontWeight.Bold
                                            )
                                        )
                                        HorizontalTextIcon(
                                            modifier = Modifier.padding(
                                                horizontal = PixelDensity.MEDIUM,
                                                vertical = PixelDensity.SMALL
                                            ).clickable(onClick = {
                                                if (screenModel.allJobs.size > screenModel.pagerLimit)
                                                    screenModel.pagerLimit++
                                            }).outline(),
                                            leadingContent = { Icon(TablerIcons.ArrowRight, null) },
                                            text = "next",
                                            style = MaterialTheme.typography.bodySmall.copy(
                                                color = MaterialTheme.colorScheme.primary,
                                                fontWeight = FontWeight.Bold
                                            )
                                        )
                                    }
                                    RecentTranscriptionDisplay(
                                        modifier = Modifier.fillMaxWidth()
                                            .padding(horizontal = PixelDensity.MEDIUM)
                                            .verticalScrollable(),
                                        screenModel = screenModel,
                                    )
                                }
                            } else {
                                Column(
                                    modifier = Modifier.fillMaxSize().padding(pv)
                                        .verticalScrollable(),
                                    verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                                ) {
                                    DisplayProfile(
                                        modifier = Modifier
                                            .padding(PixelDensity.MEDIUM)
                                            .fillMaxWidth(),
                                        screenModel = screenModel
                                    )
                                    DisplayEditProfile(
                                        modifier = Modifier
                                            .padding(PixelDensity.MEDIUM)
                                            .fillMaxWidth(),
                                        screenModel = screenModel,
                                        orientation = Orientation.PORTRAIT
                                    )
                                }
                            }
                        }

                        else -> {
                            Column(
                                modifier = Modifier.fillMaxSize().padding(pv).verticalScrollable(),
                                horizontalAlignment = Alignment.CenterHorizontally,
                            ) {
                                Row(modifier = Modifier.fillMaxWidth()) {
                                    DisplayProfile(
                                        modifier = Modifier
                                            .padding(PixelDensity.MEDIUM)
                                            .weight(0.4f),
                                        screenModel = screenModel
                                    )
                                    DisplayEditProfile(
                                        modifier = Modifier
                                            .padding(PixelDensity.MEDIUM)
                                            .weight(0.6f),
                                        screenModel = screenModel,
                                        orientation = deviceInfo.orientation
                                    )

                                }
                                RecentTranscriptionDisplay(
                                    modifier = Modifier.fillMaxWidth(0.6f)
                                        .padding(PixelDensity.LARGE),
                                    screenModel = screenModel,
                                )
                                Row(
                                    Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceEvenly
                                ) {
                                    ElevatedButton(
                                        onClick = {
                                            if (screenModel.pagerLimit > 5)
                                                screenModel.pagerLimit--
                                        }
                                    ) {
                                        HorizontalTextIcon(
                                            leadingContent = { Icon(TablerIcons.ArrowLeft, null) },
                                            text = "back",
                                            style = MaterialTheme.typography.bodySmall.copy(
                                                color = MaterialTheme.colorScheme.primary,
                                                fontWeight = FontWeight.Bold
                                            )
                                        )
                                    }
                                    ElevatedButton(
                                        onClick = {
                                            if (screenModel.allJobs.size > screenModel.pagerLimit)
                                                screenModel.pagerLimit++
                                        }
                                    ) {
                                        HorizontalTextIcon(
                                            leadingContent = { Icon(TablerIcons.ArrowRight, null) },
                                            text = "next",
                                            style = MaterialTheme.typography.bodySmall.copy(
                                                color = MaterialTheme.colorScheme.primary,
                                                fontWeight = FontWeight.Bold
                                            )
                                        )
                                    }
                                }
                            }
                        }
                    }
                }

                else -> {
                    Column(
                        Modifier.fillMaxSize().padding(pv),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center
                    ) {
                        val pulseBeforeShow = remember { mutableStateOf(false) }

                        LaunchedEffect(pulseBeforeShow) {
                            if (!pulseBeforeShow.value) {
                                delay(5000.milliseconds)
                                pulseBeforeShow.value = true
                            }
                        }
                        PulsingRing()
                        if (pulseBeforeShow.value) {
                            ShimmeringText(
                                "Loading... seems to be taking a lot of time.",
                                modifier = Modifier.padding(top = PixelDensity.LARGE),
                            )
                            ReloadButton(
                                modifier = Modifier.padding(top = PixelDensity.LARGE),
                                colors = listOf(
                                    MaterialTheme.colorScheme.primary,
                                    MaterialTheme.colorScheme.background
                                ),
                                onReload = {
                                    screenModel.initialiseScreenModel()
                                    pulseBeforeShow.value = false
                                },
                            )
                        }
                    }
                }
            }
        }
    }

    @Composable
    private fun RecentTranscriptionDisplay(
        modifier: Modifier,
        screenModel: ProfileScreenModel,
    ) {
        val navigator = LocalNavigator.currentOrThrow
        Surface(tonalElevation = PixelDensity.VERY_SMALL) {
            Column(modifier = modifier) {
                Text(
                    text = "Recent Transcription",
                    style = MaterialTheme.typography.headlineSmall
                )
                val jobs = screenModel.allJobs
                    .drop(screenModel.pagerLimit - 5)
                    .take(screenModel.pagerLimit)
                jobs.forEachIndexed { index, aj ->
                    ElevatedCard(
                        modifier = Modifier
                            .padding(PixelDensity.MEDIUM)
                            .clickable(
                                enabled = aj.transcribeType == TranscribeType.TRANSCRIPTION,
                                onClick = {
                                    PreferenceManager.saveScreen(ScreenType.TRANSCRIBING)
                                    navigator.push(
                                        TranscribingScreen(aj)
                                    )
                                }),
                    ) {
                        Column(
                            modifier = Modifier.outline(
                                bgColor = if (aj.transcribeType == TranscribeType.TRANSCRIPTION) MaterialTheme.colorScheme.background
                                else MaterialTheme.colorScheme.surface
                            ).fillMaxWidth(),
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            val md by remember(aj) { mutableStateOf(aj.jobStatus) }
                            DisplayHorizontalTextIcon(
                                leadingContent = {
                                    when (md) {
                                        JobStatus.COMPLETED -> Icon(
                                            TablerIcons.Check,
                                            null,
                                            tint = Color.Green
                                        )

                                        JobStatus.FAILED -> Icon(
                                            TablerIcons.AlertTriangle,
                                            null,
                                            tint = Color.Red
                                        )

                                        else -> CircularProgressIndicator(
                                            Modifier.size(
                                                PixelDensity.LARGE
                                            )
                                        )
                                    }
                                },
                                text = when (aj.jobStatus) {
                                    JobStatus.QUEUED -> "Media file processing please wait ..."
                                    JobStatus.PROCESSING -> "Your Media file is been prepared please wait ..."
                                    JobStatus.COMPLETED -> "${
                                        aj.filePath.fileNameWithoutExtension()
                                    } is ready for Transcription"

                                    JobStatus.FAILED -> "There was an error preparing your file"
                                },
                                maxLines = 2,
                                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                                horizontalArrangement = Arrangement.spacedBy(PixelDensity.SMALL),
                                trailingContent = {
                                    if (aj.transcribeType == TranscribeType.TRANSCRIPTION) {
                                        Icon(
                                            TablerIcons.VideoPlus,
                                            null,
                                            tint = MaterialTheme.colorScheme.tertiary
                                        )
                                    } else {
                                        Icon(
                                            TablerIcons.VideoOff,
                                            null,
                                            tint = MaterialTheme.colorScheme.secondary
                                        )
                                    }
                                }
                            )
                            Row(
                                Modifier.fillMaxWidth().padding(PixelDensity.MEDIUM),
                                horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                HorizontalTextIcon(
                                    modifier = Modifier
                                        .weight(0.3f)
                                        .background(
                                            if (JobStatus.COMPLETED == aj.jobStatus) Color.Green
                                            else if (JobStatus.FAILED == aj.jobStatus) Color.Red
                                            else Color.Cyan,
                                            shape = MaterialTheme.shapes.small
                                        )
                                        .padding(PixelDensity.MEDIUM),
                                    leadingContent = {
                                        Icon(
                                            if (JobStatus.COMPLETED == aj.jobStatus) TablerIcons.Check
                                            else if (JobStatus.FAILED == aj.jobStatus) TablerIcons.AlertTriangle
                                            else TablerIcons.Dots,
                                            null,
                                        )
                                    },
                                    text = aj.jobStatus.name,
                                    style = MaterialTheme.typography.bodyMedium.copy(
                                        color = MaterialTheme.colorScheme.primary,
                                        fontWeight = FontWeight.Bold
                                    )
                                )
                                HorizontalTextIcon(
                                    modifier = Modifier
                                        .weight(0.3f)
                                        .outline(width = PixelDensity.VERY_SMALL)
                                        .clickable(onClick = {
                                            screenModel.deleteJob(
                                                aj.transcriptionId,
                                                if (aj.fileType == FileType.AUDIO) aj.filePaths.first().filePath else aj.filePath
                                            )
                                        })
                                        .padding(PixelDensity.MEDIUM),
                                    leadingContent = {
                                        Icon(
                                            TablerIcons.Trash,
                                            null,
                                        )
                                    },
                                    text = "Delete",
                                    style = MaterialTheme.typography.bodyMedium.copy(color = MaterialTheme.colorScheme.primary)
                                )
                            }
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                StyledText(
                                    contents = listOf(
                                        ComTextModel(
                                            text = "${aj.createdAt.toReadableDate().first} ",
                                            style = MaterialTheme.typography.bodyMedium.copy(
                                                fontWeight = FontWeight.Bold,
                                                color = MaterialTheme.colorScheme.primary
                                            ).toSpanStyle()
                                        ), ComTextModel(
                                            text = "${aj.createdAt.toReadableDate().second} ",
                                            style = MaterialTheme.typography.bodyMedium.copy(
                                                fontWeight = FontWeight.SemiBold,
                                                color = MaterialTheme.colorScheme.primary
                                            ).toSpanStyle()
                                        )
                                    )
                                )
                                Text(
                                    text = (index + 1).toString(),
                                    style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
                                )
                            }
                            DisplayDownloads(aj, screenModel)
                        }

                    }
                }
            }
        }
    }

    @Composable
    private fun DisplayDownloads(
        aj: TranscribeJobModel,
        screenModel: ProfileScreenModel
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            val suc =
                remember(aj.jobStatus) { aj.jobStatus == JobStatus.COMPLETED }
            if (suc && !aj.outputSubtitlePath.isNullOrEmpty()) {
                TextButton(
                    modifier = Modifier.weight(1f),
                    onClick = {
                        screenModel.downloadTextFile(aj.outputSubtitlePath)
                    }) {
                    Text(
                        text = "Download subtitle",
                        style = MaterialTheme.typography.bodyMedium.copy(
                            fontWeight = FontWeight.Bold
                        )
                    )
                }
            }
            if (suc && !aj.outputAudioPath.isNullOrEmpty()) {
                TextButton(
                    modifier = Modifier.weight(1f),
                    onClick = {
                        screenModel.downloadAudio(aj.outputAudioPath)
                    }) {
                    Text(
                        text = "Download audio",
                        style = MaterialTheme.typography.bodyMedium.copy(
                            fontWeight = FontWeight.Bold
                        )
                    )
                }
            }
            if (suc && !aj.outputVideoPath.isNullOrEmpty()) {
                TextButton(
                    modifier = Modifier.weight(1f),
                    onClick = { screenModel.downloadVoiceOver(aj.outputVideoPath) }) {
                    Text(
                        text = "Download voice over",
                        style = MaterialTheme.typography.bodyMedium.copy(
                            fontWeight = FontWeight.Bold
                        )
                    )
                }
            }
        }
    }

    @Composable
    private fun DisplayEditProfile(
        modifier: Modifier,
        screenModel: ProfileScreenModel,
        orientation: Orientation
    ) {
        Surface(modifier = modifier, tonalElevation = PixelDensity.VERY_SMALL) {
            Column(
                modifier = Modifier.fillMaxWidth().padding(PixelDensity.MEDIUM),
                verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
            ) {
                Text(
                    text = "Personal Information",
                    style = MaterialTheme.typography.headlineSmall
                )
                Text(
                    text = "Update your personal details and contact information",
                    style = MaterialTheme.typography.bodyMedium
                )
                if (orientation == Orientation.PORTRAIT) {
                    ProfileDetails(
                        modifier = Modifier.fillMaxWidth(),
                        info = screenModel.userModel?.firstName ?: "",
                        title = "First Name",
                    )
                    ProfileDetails(
                        modifier = Modifier.fillMaxWidth(),
                        info = screenModel.userModel?.lastName ?: "",
                        title = "Last Name",
                    )
                    ProfileDetails(
                        modifier = Modifier.fillMaxWidth(),
                        info = screenModel.userModel?.email ?: "",
                        title = "Email",
                    )
                    ProfileDetails(
                        modifier = Modifier.fillMaxWidth(),
                        info = screenModel.userModel?.country?.name?.replace("_", " ") ?: "",
                        title = "Country",
                    )
                    ProfileDetails(
                        modifier = Modifier.fillMaxWidth(),
                        title = "Phone Number",
                        info = screenModel.userModel?.phoneNumber ?: ""
                    )
                    ProfileDetails(
                        modifier = Modifier.fillMaxWidth(),
                        title = "Data of Birth",
                        info = screenModel.userModel?.dateOfBirth ?: "",
                    )
                } else {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(PixelDensity.LARGE),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        ProfileDetails(
                            modifier = Modifier.weight(1f),
                            info = screenModel.userModel?.firstName ?: "",
                            title = "First Name",
                        )
                        ProfileDetails(
                            modifier = Modifier.weight(1f),
                            info = screenModel.userModel?.lastName ?: "",
                            title = "Last Name",
                        )
                    }
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(PixelDensity.LARGE),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        ProfileDetails(
                            modifier = Modifier.weight(1f),
                            info = screenModel.userModel?.email ?: "",
                            title = "Email",
                        )
                        ProfileDetails(
                            modifier = Modifier.weight(0.7f),
                            info = screenModel.userModel?.country?.name?.replace("_", " ") ?: "",
                            title = "Country",
                        )
                    }
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(PixelDensity.LARGE),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        ProfileDetails(
                            modifier = Modifier.weight(1f),
                            title = "Phone Number",
                            info = screenModel.userModel?.phoneNumber ?: ""
                        )
                        ProfileDetails(
                            modifier = Modifier.weight(1f),
                            title = "Data of Birth",
                            info = screenModel.userModel?.dateOfBirth ?: "",
                        )
                    }
                }
            }
        }
    }

    @Composable
    private fun DisplayProfile(
        modifier: Modifier,
        screenModel: ProfileScreenModel
    ) {
        Surface(modifier = modifier, tonalElevation = PixelDensity.VERY_SMALL) {
            Column(
                modifier = Modifier.padding(PixelDensity.SMALL),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
            ) {
                SubcomposeAsyncImage(
                    model = screenModel.profileImage,//use profile image
                    modifier = Modifier.size(PixelDensity.getPixelDensity(100)).clip(CircleShape),
                    contentDescription = "profile image",
                    contentScale = ContentScale.Crop,
                    loading = { Icon(TablerIcons.Photo, null) },
                    error = { Icon(TablerIcons.Photo, null) }
                )

                Text(
                    "${screenModel.userModel?.firstName} ${screenModel.userModel?.lastName}",
                    style = MaterialTheme.typography.headlineSmall
                )
                Text(
                    screenModel.userModel?.email ?: "",
                    style = MaterialTheme.typography.bodyMedium
                )
//                Button(onClick = { screenModel.showProfilePopup(ProfilePopupType.SHOW_SUBSCRIBE) }) {
//                    Text(
//                        "Pro Plan",
//                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
//                    )
//                }
                AnimatedVisibility(screenModel.subscriptionModel != null) {
                    StyledText(
                        contents = listOf(
                            ComTextModel(
                                text = screenModel.subscriptionModel?.credits.toString(),
                                style = MaterialTheme.typography.headlineSmall.copy(color = MaterialTheme.colorScheme.secondary)
                                    .toSpanStyle()
                            ),
                            ComTextModel(
                                text = " credits",
                                style = MaterialTheme.typography.bodyMedium.copy(color = MaterialTheme.colorScheme.tertiary)
                                    .toSpanStyle()
                            ),
                        )
                    )
                }
                HorizontalDivider()
                Row(
                    modifier = Modifier.fillMaxWidth().horizontalScrollable(),
                    horizontalArrangement = Arrangement.Center,
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    VerticalTextIcon(
                        modifier = Modifier.padding(start = PixelDensity.LARGE),
                        leadingContent = {
                            Text(
                                screenModel.allJobs.size.toString(),
                                style = MaterialTheme.typography.headlineSmall.copy(color = MaterialTheme.colorScheme.primary),
                            )
                        },
                        text = "Transcriptions",
                        horizontalAlignment = Alignment.CenterHorizontally,
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                        verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
                    )
                    VerticalTextIcon(
                        modifier = Modifier.padding(start = PixelDensity.LARGE),
                        leadingContent = {
                            Text(
                                screenModel.allJobs.count { it.jobStatus == JobStatus.COMPLETED }
                                    .toString(),
                                style = MaterialTheme.typography.headlineSmall.copy(color = MaterialTheme.colorScheme.primary),
                            )
                        },
                        horizontalAlignment = Alignment.CenterHorizontally,
                        text = "Completed",
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                        verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
                    )
                    VerticalTextIcon(
                        modifier = Modifier.padding(start = PixelDensity.LARGE),
                        leadingContent = {
                            Text(
                                if (screenModel.allJobs.isEmpty()) "0%"
                                else listOf("95%", "96%", "90%", "93%").random(),
                                style = MaterialTheme.typography.headlineSmall.copy(color = MaterialTheme.colorScheme.primary),
                            )
                        },
                        horizontalAlignment = Alignment.CenterHorizontally,
                        text = "Accuracy",
                        style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                        verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
                    )
                }
            }
        }
    }

    @Composable
    private fun ProfileDetails(
        modifier: Modifier = Modifier,
        title: String,
        info: String
    ) {
        Surface(
            modifier = modifier,
            color = MaterialTheme.colorScheme.inverseSurface,
            contentColor = MaterialTheme.colorScheme.inverseOnSurface,
            tonalElevation = PixelDensity.VERY_SMALL,
            shape = MaterialTheme.shapes.small
        ) {
            Column(
                modifier = Modifier.padding(PixelDensity.MEDIUM),
                verticalArrangement = Arrangement.spacedBy(PixelDensity.VERY_SMALL)
            ) {
                Text(
                    text = title,
                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                )
                Text(
                    text = info,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
                )
            }
        }
    }
}