package api.auth.kimdeo.model

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable


@Serializable
data class GenerateVoiceRequestModel(
    @SerialName("login_model")
    val logInModel: LogInModel,
    @SerialName("json_file_path")
    val jsonFilePath: String,
    @SerialName("job_id")
    val jobId: String,
    @SerialName("language_code")
    val languageCode: String,
)


@Serializable
data class ResponseMessage<T>(
    val data: T? = null,
    val message: String,
    val errorMessage: String = "",
    val status: Boolean
)
@Serializable
data class GoogleSignInRequest(
    val idToken: String
)