package api.auth.kimdeo.screens.v_player

import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.Surface
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.ui.Modifier
import api.auth.kimdeo.VideoPlayer
import api.auth.kimdeo.core.navigateBack
import api.auth.kimdeo.screens.ScreenType
import api.auth.kimdeo.ui.PixelDensity
import cafe.adriel.voyager.core.model.rememberNavigatorScreenModel
import cafe.adriel.voyager.core.screen.Screen
import cafe.adriel.voyager.navigator.LocalNavigator
import cafe.adriel.voyager.navigator.currentOrThrow
import io.github.vinceglb.filekit.mimeType


object KimdeoPlayVideoScreen : Screen {
    @Composable
    override fun Content() {
        val navigator = LocalNavigator.currentOrThrow
        // Reuses the same instance
        val screenModel = navigator.rememberNavigatorScreenModel { KimdeoSelectVideoScreenModel() }
        LaunchedEffect(Unit) {
            screenModel.resetScreenModel()
        }
        Surface(modifier = Modifier.fillMaxSize()) {
            VideoPlayer(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(PixelDensity.SMALL),
                platformFile = screenModel.platformFile!!,
//                bytes = screenModel.fileByteArray!!,
                mimeType = screenModel.platformFile?.mimeType()?.toString()
                    ?: "video/mp4",
                onVolume = { volume ->
                    screenModel.aiVolume = volume / 10.0
                    screenModel.audioController?.setVolume(volume / 10.0)
                },
                onBack = {
                    screenModel.onBackPressed {
                        navigator.navigateBack(ScreenType.VIDEOPLAYER)
                    }
                },
                interaction = { videoInteraction ->
                    screenModel.attachVideoController(videoInteraction)
                },
                onForwardClicked = {},
                onBackwardClicked = {}
            )
        }

        // 3. Isolated Reactive Event Loop tied strictly to the screen lifecycle
        LaunchedEffect(screenModel.videoController) {
            val controller = screenModel.videoController ?: return@LaunchedEffect
            // Process the state stream cleanly without side-effects inside .map
            controller.state
                .collect { state ->
                    val audioConfig = screenModel.audioFilePath ?: return@collect
                    //************************************ manage forward and backward seek ***************************
                    // Detect seeking
                    if (state.isPlaying && state.currentTime != screenModel.lastSeekTime) {
                        screenModel.lastSeekTime = state.currentTime

                        // Find and load correct audio track for seek position
                        val audioTrack = screenModel.audioFilePaths.find { track ->
                            state.currentTime >= track.startTime &&
                                    state.currentTime <= track.endTime
                        }

                        if (audioTrack != null && audioTrack != screenModel.audioFilePath) {
                            val audioPosition = (state.currentTime - audioTrack.startTime)
                                .coerceAtLeast(0.0)

                            screenModel.updatePlayingAudio(audioTrack)
                            screenModel.audioController?.seek(audioPosition)
                            screenModel.audioPosition =
                                screenModel.audioFilePaths.indexOf(audioTrack)
                        }
                    }

                    // *************************** manage pause play and load audio file path******************************************************
                    val currentTime = state.currentTime
                    val audioState = screenModel.audioController?.state?.value

                    /* A. Check End Threshold to trigger background loading */
                    audioConfig.endTime.let { endTime ->
                        if (currentTime >= endTime && !screenModel.loadingNextAudio) {
                            screenModel.updatePlayingAudio()
                        }
                    }

                    // B. Check Start Threshold to play the audio track
                    val targetStart = audioConfig.startTime
                    if (audioState != null) {
                        val hasStartedPlaying = currentTime >= targetStart
                        val isAudioStopped = !audioState.isPlaying
                        // Safely check if the audio track hasn't finished completely yet
                        val isAudioAlreadyFinished =
                            audioState.duration > 0.0 && audioState.currentTime >= audioState.duration

                        if (hasStartedPlaying && isAudioStopped && !isAudioAlreadyFinished) {
                            screenModel.audioController?.play()
                        }

                        // C. SYNC PAUSE/RESUME: Match audio playback state with video playback state
                        if (hasStartedPlaying && !isAudioAlreadyFinished) {
                            val videoIsPlaying = state.isPlaying

                            if (videoIsPlaying && !audioState.isPlaying) {
                                // Video is playing but audio is paused - resume audio
                                screenModel.audioController?.play()
                            } else if (!videoIsPlaying && audioState.isPlaying) {
                                // Video is paused but audio is playing - pause audio
                                screenModel.audioController?.pause()
                            }
                        }
                    }
                }
        }
    }
}
