package api.auth.kimdeo.model

import androidx.compose.foundation.layout.ColumnScope
import androidx.compose.runtime.Composable
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable


sealed class ConnectionState() {
    data class OnSucsess(val data: String) : ConnectionState()
    data class OnFailure(val data: String) : ConnectionState()
    object OnLoading : ConnectionState()
    object None : ConnectionState()
}

sealed class FileConnectionState {
    data class OnGotten(val data: String) : FileConnectionState()
    data class OnSuccess(val data: String) : FileConnectionState()
    data class OnFailure(val data: String) : FileConnectionState()
    object OnUploading : FileConnectionState()
    object None : FileConnectionState()
}

enum class UuidStrength{
    SIMPLE,MEDIUM,HARD,TOUGH
}



@Serializable
data class InvokeLogIn(
    val token: String,
    @SerialName("should_login")
    val shouldLogin: Boolean,
    @SerialName("already_login")
    val alreadyLogin: Boolean
) {
    companion object {
        fun empty() = InvokeLogIn("", true, alreadyLogin = false)
    }
}

data class ListItem<T>(
    val id: Int,
    val boolean: Boolean,
    val dataType: T
)

data class PopupModel(
    val show: Boolean = false,
    val title: String = "",
    val description: String = "",
    val content: @Composable () -> Unit = {},
    val isDismissible: Boolean = true,
)
data class ConfirmPopupModel(
    val show: Boolean = false,
    val title: String = "",
    val description: String = "",
    val content: @Composable (ColumnScope.() -> Unit) = {},
    val isDismissible: Boolean = true,
)

interface Disposable {
    fun dispose()
}